function folderReady()
    if type(isfolder)=="function" then
        local ok,yes=pcall(isfolder,FOLDER);if ok and yes then return true end
    end
    if type(makefolder)~="function" then return false end
    local ok=pcall(makefolder,FOLDER)
    if type(isfolder)=="function" then
        local checked,yes=pcall(isfolder,FOLDER);if checked then return yes==true end
    end
