function log(message,level,key)
    if level=="warning" then
        local now=os.clock()
        key=key or tostring(message)
        local previous=logWarningTimes[key]
        if not previous or now-previous>=60 then
            logWarningTimes[key]=now
            warn("[Adonis TAS] "..tostring(message))
        end
    end
    if not debugLogs then return end
    local line=os.date("!%Y-%m-%dT%H:%M:%SZ").." "..tostring(message)
    logLines[#logLines+1]=line
    if #logLines>3000 then table.remove(logLines,1) end
    logDirty=true;logRevision=logRevision+1
    if level~="warning" then print("[Adonis TAS] "..tostring(message)) end
end
function setStatus(text,holdSeconds)
    if holdSeconds then stickyStatus,stickyUntil=text,os.clock()+holdSeconds end
    if stickyStatus and os.clock()<stickyUntil and not holdSeconds and not emergency then return end
    if stickyUntil and os.clock()>=stickyUntil then stickyStatus,stickyUntil=nil,nil end
