function find(root,...)
    for _,name in ipairs({...}) do root=root and root:FindFirstChild(name) end
    return root
end
function visible(object)
    if not object or not object:IsDescendantOf(pg) then return false end
    while object and object~=pg do
        if object:IsA("GuiObject") and not object.Visible then return false end
        if object:IsA("LayerCollector") and not object.Enabled then return false end
        object=object.Parent
    end
    return true
end
function loadConfig()
    if type(readfile)~="function" then return end
    local ok,text=pcall(readfile,configPath);if not ok then return end
    local decoded,data=pcall(function() return Http:JSONDecode(text) end)
    if not decoded or type(data)~="table" then log("Ignored invalid config") return end
    data=type(data.options)=="table" and data.options or data
    for key,base in pairs(defaults) do
        if type(data[key])==type(base) then
            if numericLimits[key] then
                local v=data[key];local limits=numericLimits[key]
                if v==v and v>=limits[1] and v<=limits[2] then config[key]=math.floor(v) end
            else config[key]=data[key] end
        end
    end
    log("Loaded config")
end
folderReady();loadConfig()
function flushFiles(force)
    if not folderReady() or type(writefile)~="function" then return false end
    local now=os.clock()
    for i=debugLogs and #diagnosticQueue or 0,1,-1 do
        local item=diagnosticQueue[i]
        local ok=pcall(function() writefile(item.path,Http:JSONEncode(item.data)) end)
        if ok then table.remove(diagnosticQueue,i) end
    end
    if debugLogs and logDirty and (force or now-lastLogFlush>=2) then
        local revision=logRevision
        local snapshot=table.concat(logLines,"\n").."\n"
        local ok,err=pcall(writefile,logPath,snapshot)
        if ok then
            if revision==logRevision then logDirty=false end
        else log("Log write: "..tostring(err),"warning","log-write") end
        lastLogFlush=now
    end
    if configDirty and config.AutoSave and not currentShot and not pendingIntent and not outstanding
        and (not busyGame or not busyGame())
        and (force or now-lastConfigFlush>=1) then
        local revision=configRevision
        local ok,err=pcall(function()
            writefile(configPath,Http:JSONEncode({version=1,options=config}))
        end)
        if ok and revision==configRevision then configDirty=false end
        if not ok then log("Config write failed: "..tostring(err),"warning","config-write") end
        lastConfigFlush=now
    end
    return true
end
end

end)()

factories["game/Data"] = (function()
-- Adonis TAS module: game/Data
-- Shared names belong to this session context, never the executor global table.
return function(context)
    setfenv(1, context)
function originalModule(object,label)
    if not object or not object:IsA("ModuleScript") then log("Missing module "..label,"warning","module-"..label) return nil end
    local ok,value=pcall(require,object)
    if ok and type(value)=="table" then return value end
    log("Cannot load original module "..label..": "..tostring(value),"warning","module-"..label);return nil
end
-- Load the game's original modules. Exported decompiler text is never executed.
Balance=originalModule(RS:FindFirstChild("Balance"),"Balance")
State=originalModule(scripts:FindFirstChild("ClientState"),"ClientState")
PlantConfig=originalModule(RS:FindFirstChild("PlantConfig"),"PlantConfig")
Request=remotes:FindFirstChild("Request")
backoff={}
function readyData() return State and State.ready==true and type(State.plants)=="table" end
function character()
    local c=player.Character
    local h=c and c:FindFirstChildOfClass("Humanoid")
    local r=c and c:FindFirstChild("HumanoidRootPart")
    if c and h and r and h.Health>0 then return c,h,r end
end
function training()
    local c=player.Character
    return c and c:GetAttribute("Training")==true
end
function myPlot()
    local name=player:GetAttribute("Plot")
    local plot=type(name)=="string" and find(workspace,"Map","Plots",name) or nil
    if not plot then return nil end
    local owner=plot:GetAttribute("OwnerUserId") or plot:GetAttribute("Owner")
    if owner~=player.UserId then return nil end
    return plot
end
end

end)()

factories["game/ThrowInput"] = (function()
-- Adonis TAS module: game/ThrowInput
-- Shared names belong to this session context, never the executor global table.
return function(context)
    setfenv(1, context)
-- Find the existing ThrowClient input handler's event and read-only phase cell.
-- No closure body or upvalue is overwritten.
-- Session slots: inputFunction,throwEvent
inputKind="unavailable"
upvaluesAPI = debug and debug.getupvalues or getupvalues
function upvalues(fn)
    if type(upvaluesAPI)~="function" then return nil end
    local ok,values=pcall(upvaluesAPI,fn)
    return ok and type(values)=="table" and values or nil
end
function bindThrowInput()
    -- Exported ThrowClient creates this event outside its Studio-only section.
    -- Its callback forwards directly to the very same aim/Continue event.
    local existing=find(pg,"ThrowFX","TestTap")
    if existing and existing:IsA("BindableEvent") then
        throwEvent=existing;inputKind="ThrowFX.TestTap";return true
    end
    if type(getconnections)~="function" or type(getfenv)~="function" then return false end
    local scriptObject=scripts:FindFirstChild("ThrowClient")
    if not scriptObject then return false end
    local ok,list=pcall(getconnections,UIS.InputBegan);if not ok then return false end
    for _,c in ipairs(list) do
        local readable,fn=pcall(function() return c.Function end)
        if not readable then fn=nil end
        if type(fn)=="function" then
            local envOK,fnEnv=pcall(getfenv,fn)
            if envOK and fnEnv and fnEnv.script==scriptObject then
                local values=upvalues(fn)
                local event,phaseFound
                for _,value in pairs(values or {}) do
                    if typeof(value)=="Instance" and value:IsA("BindableEvent") then event=value end
                    if value=="idle" or value=="aiming" or value=="result" or value=="flight"
                        or value=="reveal" or value=="throwing" or value=="home" then phaseFound=true end
                end
                if event and phaseFound then inputFunction,throwEvent=fn,event;inputKind="input closure";return true end
            end
        end
    end
    return false
end
function throwPhase()
    -- Use the phase published by the native Heartbeat, independently of our
    -- currentShot lock. A rejected throw can abort to idle without a new plant.
    local fx=pg:FindFirstChild("ThrowFX")
    local state=fx and fx:GetAttribute("State")
    if state=="idle" or state=="aiming" or state=="throwing" or state=="flight"
        or state=="reveal" or state=="result" or state=="home" then return state end
    for _,value in pairs(inputFunction and upvalues(inputFunction) or {}) do
        if type(value)=="string" and (value=="idle" or value=="aiming" or value=="result"
            or value=="flight" or value=="throwing" or value=="reveal" or value=="home") then return value end
    end
    if visible(find(pg,"HudLancer","Jauge")) then
        return currentShot and "throwing" or "aiming"
    end
    local revealTop=pg:FindFirstChild("RevealTop")
    if revealTop then
        for _,object in ipairs(revealTop:GetDescendants()) do
            if (object:IsA("TextLabel") or object:IsA("TextButton")) and visible(object)
                and object.Text:lower():find("to continue",1,true) then return "result" end
        end
        if visible(revealTop) then return "reveal" end
    end
    if visible(find(pg,"HudVol","Haut")) then return "flight" end
    -- A stale result template is never treated as the current result.
    local _,_,root=character()
    local camera=workspace.CurrentCamera
    if root and not root.Anchored and not training() and camera
        and camera.CameraType==Enum.CameraType.Custom then return "idle" end
    if training() then return "training" end
    return "unknown"
end
-- Published State can reach idle before the native camera/HUD tweens finish.
-- These are read-only checks; never hide the bars or unlock the character here.
function nativeVisualBusy()
    if visible(find(pg,"HudLancer","Jauge")) or visible(find(pg,"HudVol","Haut"))
        or visible(pg:FindFirstChild("RevealTop"))
        or visible(find(pg,"ChoixApresLancer","Boutons")) then return true end
    for _,name in ipairs({"Tint","Dim"}) do
        local frame=find(pg,"ThrowFX",name)
        if frame and visible(frame) and frame.BackgroundTransparency<0.99 then return true end
    end
    for _,name in ipairs({"ThrowFlash","ThrowBlackout"}) do
        local gui=pg:FindFirstChild(name)
        for _,frame in ipairs(gui and gui:GetChildren() or {}) do
            if frame:IsA("Frame") and visible(frame) and frame.BackgroundTransparency<0.99 then return true end
        end
    end
    local top=find(pg,"ThrowBars","Top")
    local bottom=find(pg,"ThrowBars","Bottom")
    if top and visible(top) and top.Position.Y.Scale>-0.099 then return true end
    if bottom and visible(bottom) and bottom.Position.Y.Scale<0.999 then return true end
    return false
end
function resetNativeControl()
    nativeIdleSince=nil
end
function nativeControlReady()
    local phase=throwPhase()
    local _,_,root=character()
    local camera=workspace.CurrentCamera
    -- TrainClient also owns a Scriptable camera and an anchored root. Its
    -- confirmed Training state must still allow StopTrain/XPBoost, while the
    -- movement helper continues to forbid any teleport until training stops.
    if (phase=="idle" or phase=="training") and root and camera and training()
        and not nativeVisualBusy() then return true end
    if (phase~="idle" and phase~="training") or not root
        or (root.Anchored and not training()) or not camera
        or camera.CameraType~=Enum.CameraType.Custom or nativeVisualBusy() then
        resetNativeControl();return false
    end
    -- Debounce a continuously free native state. This is a movement barrier,
    -- never a timeout that declares a throw or a purchase successful.
    local now=os.clock()
    if not nativeIdleSince then nativeIdleSince=now end
    return now-nativeIdleSince>=1
end
function captureThrowAbort()
    -- CharacterAdded has a permanent ThrowClient callback which closes over
    -- its native abort function. Read it; never overwrite closure upvalues.
    if type(getconnections)~="function" or type(getfenv)~="function" then return end
    local scriptObject=scripts:FindFirstChild("ThrowClient")
    if not scriptObject then return end
    local ok,list=pcall(getconnections,player.CharacterAdded)
    if not ok or type(list)~="table" then return end
    local found
    for _,connection in ipairs(list) do
        local readable,callback=pcall(function()return connection.Function end)
        local envOK,origin=false,nil
        if readable and type(callback)=="function" then envOK,origin=pcall(getfenv,callback) end
        if envOK and origin and origin.script==scriptObject then
            local phase,functions=nil,{}
            for _,value in pairs(upvalues(callback) or {}) do
                if value=="aiming" or value=="idle" or value=="throwing" then phase=value end
                if type(value)=="function" then functions[#functions+1]=value end
            end
            if phase and #functions==1 then
                local fn=functions[1]
                local fnOK,fnEnv=pcall(getfenv,fn)
                local hasPlayer,hasInput,hasPhase,hasEvent,tables,functionsCount=false,false,false,false,0,0
                for _,value in pairs(upvalues(fn) or {}) do
                    if value==player then hasPlayer=true end
