factories["game/Movement"] = (function()
-- Adonis TAS module: game/Movement
-- Shared names belong to this session context, never the executor global table.
return function(context)
    setfenv(1, context)
function activityValid(generation,guard)
    return alive and not emergency and cancellation==generation and (not guard or guard())
end

-- All travel uses a single teleport owned by the coordinator. Never unanchor
-- a character or move it while the native training/throw sequence owns it.
function teleportNear(target,radius,guard)
    local generation=cancellation
    local c,h,r=character()
    if not c or r.Anchored or not activityValid(generation,guard) or outstanding
        or env.__AdonisTASOutstanding or throwFault or busyGame() or training() then return false end
    local position=typeof(target)=="Vector3" and target or target.Position
    if (r.Position-position).Magnitude<=radius then return true end
    local exclude={c}
    if typeof(target)=="Instance" and target:IsA("BasePart") then
        -- Stand beside counters/signs rather than inside their solid geometry.
        local forward=target.CFrame.LookVector
        local flat=Vector3.new(forward.X,0,forward.Z)
        if flat.Magnitude>0.01 then position=position+flat.Unit*(target.Size.Z*0.5+2) end
        exclude[#exclude+1]=target
    end
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances=exclude
    params.RespectCanCollide=true
    local ok,ground=pcall(function()
        return workspace:Raycast(position+Vector3.new(0,8,0),Vector3.new(0,-128,0),params)
    end)
    if not ok or not ground then setStatus("Tele: cho mat dat tai diem den stream vao client");return false end
    local clearance=math.max(3,h.HipHeight+r.Size.Y*0.5+0.1)
    local destination=Vector3.new(position.X,ground.Position.Y+clearance,position.Z)
    -- Do not accept a floor on a different map level from the requested point.
    if math.abs(destination.Y-position.Y)>math.max(8,radius) then
        setStatus("Tele: chua xac dinh duoc mat dat gan diem den");return false
    end
    if not activityValid(generation,guard) or player.Character~=c or h.Health<=0 or r.Anchored
        or outstanding or env.__AdonisTASOutstanding or throwFault or busyGame() or training() then return false end
    r.AssemblyLinearVelocity=Vector3.new(0,0,0)
    r.AssemblyAngularVelocity=Vector3.new(0,0,0)
    lastTeleportAt=os.clock()
    r.CFrame=CFrame.new(destination)*r.CFrame.Rotation
    -- Let local pad triggers and replication run before a purchase/prompt.
    task.wait(0.2)
    if not activityValid(generation,guard) or player.Character~=c or h.Health<=0 or r.Anchored
        or outstanding or env.__AdonisTASOutstanding or throwFault or busyGame() or training() then return false end
    if (r.Position-destination).Magnitude>math.max(3,radius) then
        setStatus("Tele: vi tri bi tra lai, cho lan thu tiep theo");return false
    end
    return true
end
end

end)()

factories["game/Requests"] = (function()
-- Adonis TAS module: game/Requests
-- Shared names belong to this session context, never the executor global table.
