    setfenv(1, context)
function call(action,args)
    if outstanding or env.__AdonisTASOutstanding or currentShot or pendingIntent
        or busyGame() or throwFault or (throwRetry and action~="StopTrain")
        or (emergency and action~="StopTrain") or not alive then return false,"busy",nil,false end
    if not Request or not Request:IsA("RemoteFunction") then return false,"Request unavailable",nil,false end
    local token={action=action,done=false}
    outstanding=token
    env.__AdonisTASOutstanding=token
    log("Request "..action)
    spawn(function()
        local ok,a,b=pcall(Request.InvokeServer,Request,action,args or {})
        token.done,token.transport,token.ok,token.result=true,ok,ok and a==true,b
        token.rejected=ok and a==false
        if outstanding==token then outstanding=nil end
        if env.__AdonisTASOutstanding==token then env.__AdonisTASOutstanding=nil end
        log(action.." reply: "..tostring(a).." / "..tostring(b))
    end)
    while alive and not token.done do
        if not emergency then setStatus("Cho phan hoi "..action) end
        task.wait(0.1)
    end
    return token.done and token.ok,token.result,token.rejected,true
end
end

