    local untilTime=os.clock()+6
    while alive and training() and os.clock()<untilTime do task.wait(0.1) end
    if not training() and activeCycle and cycle==activeCycle and activeCycle.phase=="train"
        and activeCycle.deadline then
        -- Pauses for upgrades/equip/sale do not consume the requested reps time.
        activeCycle.remaining=math.max(0,activeCycle.deadline-os.clock())
        activeCycle.deadline=nil
    end
    return not training() and ok
