function startTraining(guard)
    if training() then return true end
    local plot=myPlot()
    local prompt=plot and find(plot,"BarStation","Bar","TrainSpot","TrainPrompt")
    if not prompt or not prompt.Enabled then return false end
    local part=prompt.Parent
    local position=part:IsA("Attachment") and part.WorldPosition or part.Position
    if not teleportNear(position,math.max(2,prompt.MaxActivationDistance-2),guard) then return false end
    if not guard() or busyGame() or not prompt.Enabled then return false end
    if type(fireproximityprompt)=="function" then
        pcall(fireproximityprompt,prompt)
    else
        prompt:InputHoldBegin();task.wait(prompt.HoldDuration+0.05);prompt:InputHoldEnd()
    end
    local untilTime=os.clock()+4
    while alive and guard() and not training() and os.clock()<untilTime do task.wait(0.1) end
    return training()
end
end

