    setfenv(1, context)
local claimed,generation,lastClaim={},0,nil
local function nativeClaim()
    if type(getconnections)~="function" then return nil,false end
    local hud=find(pg,"XPBoostHud")
    if not hud then return nil,false end
    -- clearOffer leaves the previous fading button alive briefly. The newest
    -- native offer is the last child; visibility/focus is deliberately ignored.
    local children=hud:GetChildren()
    local button
    for i=#children,1,-1 do
        if children[i].Name=="XPOffer" and children[i]:IsA("GuiButton") then button=children[i];break end
    end
    if not button then return nil,true end
    local ok,list=pcall(getconnections,button.Activated)
    if not ok or type(list)~="table" then return nil,true end
    local candidates,seen={},{}
    local trainClient=scripts and scripts:FindFirstChild("TrainClient")
    for _,connection in ipairs(list)do
        local readable,fn=pcall(function()return connection.Function end)
        if readable and type(fn)=="function" and not seen[fn] then
            seen[fn]=true
            local origin
            if type(getfenv)=="function" then
                local read,fnEnv=pcall(getfenv,fn)
                if read and fnEnv then origin=fnEnv.script end
            end
            if trainClient and origin==trainClient then return fn,true end
            candidates[#candidates+1]=fn
        end
    end
    if #candidates==1 then return candidates[1],true end
    return nil,true
end
function clearTrainingOffers()
    generation=generation+1
