    end
end
function receiveTrainingOffer(data)
    if type(data)~="table" or (type(data.id)~="string" and type(data.id)~="number") then return end
    if data.id=="" or (type(data.id)=="number" and (data.id~=data.id or math.abs(data.id)==math.huge)) then return end
    local ttl=tonumber(data.ttl) or 3.6
    if ttl~=ttl or ttl<=0 or ttl==math.huge or claimed[data.id] then return end
    if offer and offer.id==data.id then return end -- do not extend a duplicate's TTL
    local now=os.clock()
    offer={id=data.id,received=now,readyAt=now+math.min(0.35,ttl*0.25),expires=now+ttl}
    if initialized and (config.AutoTap or config.Loop) then spawn(serviceAutoTap) end
end
function serviceAutoTap()
    local current=offer
    if not current then return false end
    local now=os.clock()
    if now>=current.expires then offer=nil;return false end
    if now<current.readyAt then return false end
    if not alive or not initialized or emergency or throwFault or throwRetry or not training()
        or not (config.AutoTap or config.Loop) or currentShot or pendingIntent
        or outstanding or env.__AdonisTASOutstanding or busyGame()
        or (lastTap and now-lastTap<0.35) then return false end
    if claimed[current.id] then offer=nil;return false end
    local fn,waitForNative=nativeClaim()
    if not fn and waitForNative then return false end
    local claimGeneration=generation
    claimed[current.id]=true;offer=nil;lastTap=now
    lastClaim={id=current.id,expires=current.expires}
    if fn then
        -- Reserve the same coordinator request slot while the native callback
        -- calls ClientState.Request. Invoke exactly one closure, no mouse or
        -- synthetic input. The live game handles nonce, UI cleanup and reply.
        local token={action="XPBoost",native=true,done=false}
        outstanding=token;env.__AdonisTASOutstanding=token
        log("Native X2 claim; id="..tostring(current.id).."; offerAge="..tostring(now-current.received))
        local ok,err=pcall(fn)
        token.done=true
        if outstanding==token then outstanding=nil end
        if env.__AdonisTASOutstanding==token then env.__AdonisTASOutstanding=nil end
        if not ok then log("Native X2 callback error; not replayed: "..tostring(err)) end
        -- An invoked callback is not itself proof of reward. XPBoost Notify
        -- above is the positive acknowledgement; never fabricate XP/multiplier.
        return ok
    end
    -- Fallback only when Volt cannot read callbacks/the native HUD is absent.
    log("X2 request fallback; id="..tostring(current.id).."; offerAge="..tostring(now-current.received))
    local ok,accepted,result,rejected=pcall(call,"XPBoost",{id=current.id})
    if ok and not accepted and result=="busy" and rejected==nil and generation==claimGeneration then
        -- call() rejected locally before sending. Keep a still-live offer for
        -- the next safe tick; never repeat an issued/rejected/uncertain request.
        claimed[current.id]=nil
        lastClaim=nil
        if alive and not offer and os.clock()<current.expires then offer=current end
    elseif not ok then log("XPBoost background claim: "..tostring(accepted)) end
    return ok and accepted==true
