    local a,errA=activateNative(gfx)
    local b,errB=activateNative(others)
    local d,errD=activateNative(effects)
    if not a or not b or not d then return false,errA or errB or errD end
    return selectedSetting("Graphics","Low","High","SetLowGfx")==profile.low
        and selectedSetting("OtherPlants","Hide","Show","SetHideOthers")==profile.hide
        and selectedSetting("Effects","On","Off","SetVfx")==profile.vfx
end
function applyFPS()
    if config.BoostFPS then
        if not nativeProfile then
            local low=selectedSetting("Graphics","Low","High","SetLowGfx")
            local hide=selectedSetting("OtherPlants","Hide","Show","SetHideOthers")
            local vfx=selectedSetting("Effects","On","Off","SetVfx")
            if low~=nil and hide~=nil and vfx~=nil then nativeProfile={low=low,hide=hide,vfx=vfx} end
        end
        pendingProfile={low=true,hide=true,vfx=false}
    else
        -- OFF explicitly means HIGH + SHOW, even if the previous session or
