function diagnoseShot(shot,result)
    if not debugLogs then return end
    local data={format="AdonisTASThrow/1",version=VERSION,placeId=game.PlaceId,
        inputKind=inputKind,automatic=shot.auto,transportOK=result[1],
        returns={},count=result.n-1,power=shot.power,phase=throwPhase(),
        aimAge=shot.aimAge,hereObserved=shot.hereObserved,emptyReply=shot.emptyReply,
        aimForwarded=shot.aimForwarded,hereForwarded=shot.hereForwarded,
        duration=os.clock()-shot.started,aimSerial=shot.aimSerial,extra=shot.extra,
        supersededRejected=shot.supersededRejected,travelAge=shot.travelAge,
        dispatch="original-namecall",retry=shot.retry,
        nativeAbortAvailable=type(shot.abortNative)=="function"}
    for i=2,result.n do data.returns[tostring(i-1)]=diagnosticValue(result[i],0,{}) end
    local path=FOLDER.."/ThrowReply_"..session.."_"..Http:GenerateGUID(false):sub(1,8)..".json"
    diagnosticQueue[#diagnosticQueue+1]={path=path,data=data}
    log("Throw reply diagnostic: "..path)
end
-- Session slots: originalSkip,ownedSkip
function setShotPresentation(shot)
    originalSkip=player:GetAttribute("SetSkipCine")
    ownedSkip=shot.fast
    -- Only use the game's own SHORT/FULL implementation for this throw.
    -- No camera lock, disabled game HUD, or extra animation timing overrides.
    player:SetAttribute("SetSkipCine",shot.fast)
end
function releasePresentation()
    if ownedSkip~=nil and player:GetAttribute("SetSkipCine")==ownedSkip then
        player:SetAttribute("SetSkipCine",originalSkip)
    end
    ownedSkip=nil
end
function installObserver()
    -- Cache before entering the hook, so Aim/Here/Collect do not perform
    -- Instance lookups that could alter the executor's namecall method state.
    local throwRemote=remotes:FindFirstChild("Throw")
    local collectRemote=remotes:FindFirstChild("Collect")
    local aimRemote=remotes:FindFirstChild("Aim")
    local hereRemote=remotes:FindFirstChild("Here")
    bridge=env.__AdonisTASNamecallBridge
    if not (type(bridge)=="table" and bridge.version==4) then
        if type(hookmetamethod)~="function" or type(getnamecallmethod)~="function" then return false end
        -- Leave an older forwarding wrapper dormant, rather than restoring over
        -- another tool's namecall hook. This version preserves the dispatch method.
        if type(bridge)=="table" then bridge.handler=nil end
        local newBridge={version=4}
        local original
        local function pack(...) return {n=select("#",...),...} end
        local unpackValues=table.unpack or unpack
        local function wrapper(self,...)
            local handler=newBridge.handler
            if not handler then return original(self,...) end
            local method=getnamecallmethod()
            if not newBridge.watched or newBridge.watched[self]~=method then return original(self,...) end
            -- begin is deliberately pure Lua: no Instance methods, GUI reads,
            -- attribute writes, logging or yielding before native dispatch.
            -- Preserve the game's original namecall rather than substituting
            -- self.InvokeServer/self.FireServer or touching unrelated remotes.
            local ok,token=pcall(handler.begin,self,method,pack(...))
            local result=pack(pcall(original,self,...))
            if ok and token then pcall(handler.finish,token,result) end
            if not result[1] then error(result[2],0) end
            return unpackValues(result,2,result.n)
        end
        local closure=wrapper
        if type(newcclosure)=="function" then
            local ok,result=pcall(newcclosure,wrapper);if not ok then return false end
            closure=result
        end
        local ok,result=pcall(hookmetamethod,game,"__namecall",closure)
        if not ok then log("Observer error: "..tostring(result),"warning","observer");return false end
        original=result;bridge=newBridge;env.__AdonisTASNamecallBridge=bridge
    end
    bridge.watched={}
    if throwRemote then bridge.watched[throwRemote]="InvokeServer" end
    for _,remote in pairs({collectRemote,aimRemote,hereRemote}) do
        bridge.watched[remote]="FireServer"
    end
    -- Snapshot only immutable IDs for result correlation. inventoryView also
    -- reads Holding via GetAttribute and must never run before native dispatch.
    local function beforePlants()
        if not State or not State.ready or type(State.plants)~="table" then return end
        local before={}
        for _,plant in pairs(State.plants) do
            if type(plant)~="table" or (type(plant.id)~="string" and type(plant.id)~="number") then return end
            local id=tostring(plant.id)
            if before[id] then return end
            before[id]=true
        end
        return before
    end
    observer={}
    observer.begin=function(remote,method,args)
        if not alive then return end
        if method=="FireServer" and remote==aimRemote then
            resetNativeControl()
            nativeAim={time=os.clock(),consumed=false,serial=(nativeAim and nativeAim.serial or 0)+1}
            return {event="Aim",aim=nativeAim}
        end
        if method=="FireServer" and remote==hereRemote then
            if nativeAim then nativeAim.hereTime=os.clock() end
            return {event="Here",aim=nativeAim}
        end
        if method=="FireServer" and remote==collectRemote then
            if currentShot then
                if currentShot.collectObserved then currentShot.ambiguous=true end
                currentShot.collectObserved=true
                currentShot.collectSync=syncGeneration
            end
            return
        end
        if method~="InvokeServer" or remote~=throwRemote then return end
        resetNativeControl()
        local superseded=currentShot and currentShot.done and currentShot.rejected
            and nativeAim and currentShot.aim~=nativeAim
        local extra=currentShot~=nil and not superseded
        local intent=pendingIntent
        local automated=intent and os.clock()-intent.time<2
        local shot={auto=automated==true,cycle=automated and intent.cycle or nil,
            fast=config.FastThrow,started=os.clock(),before=beforePlants(),extra=extra or nil,
            preSync=syncGeneration,power=args[1],done=false,generation=cancellation,
            aim=nativeAim,aimSerial=nativeAim and nativeAim.serial,
            aimAge=nativeAim and os.clock()-nativeAim.time,
            hereObserved=nativeAim and nativeAim.hereTime~=nil,
            aimForwarded=nativeAim and nativeAim.forwarded==true,
            hereForwarded=nativeAim and nativeAim.hereForwarded==true,
            travelAge=lastTeleportAt and os.clock()-lastTeleportAt,
            abortNative=automated and intent.abortNative or nil,
            retry=automated and throwRetry~=nil or nil,
            supersededRejected=superseded==true or nil,parent=extra and currentShot or nil}
        if nativeAim then nativeAim.consumed=true end
        pendingIntent=nil
        if not extra then
            currentShot=shot
            if automated then throwRetry=nil end
        end
        return shot
    end
    observer.finish=function(shot,result)
        if shot.event then
            if shot.aim and shot.event=="Aim" then shot.aim.forwarded=result[1]==true end
            if shot.aim and shot.event=="Here" then shot.aim.hereForwarded=result[1]==true end
            return
        end
        shot.done=true
        shot.response=result[1] and result[2] or nil
        shot.accepted=result[1] and type(shot.response)=="table"
            and type(shot.response.plant)=="string" and type(shot.response.distance)=="number"
        shot.emptyReply=result[1] and result[2]==nil
        -- The native animation gate requires a table. Nil/false abort, while
        -- other scalar replies cannot produce a native result either.
        shot.rejected=not result[1] or type(shot.response)~="table"
        if shot.extra and shot.parent and shot.accepted then shot.parent.ambiguous=true end
        log((shot.auto and "Auto" or "Manual").." Throw observed; power="..tostring(shot.power)
            ..(shot.extra and "; additional request" or ""))
        diagnoseShot(shot,result)
        log("Throw response: transport="..tostring(result[1]).."; type="..typeof(result[2])
            .."; accepted="..tostring(shot.accepted)..(not result[1] and ("; error="..tostring(result[2])) or ""))
    end
    bridge.handler=observer
    return true
end
observerOK=installObserver()
end

end)()

factories["features/Notifications"] = (function()
-- Adonis TAS module: features/Notifications
-- Shared names belong to this session context, never the executor global table.
return function(context)
    setfenv(1, context)
if State and typeof(State.Changed)=="Instance" then
    connect(State.Changed.Event,function() syncGeneration=syncGeneration+1 end)
end
if State and typeof(State.Event)=="Instance" then
    connect(State.Event.Event,function(kind,data)
        if kind=="XPOffer" then receiveTrainingOffer(data)
        elseif kind=="XPBoost" then confirmTrainingBoost()
        elseif kind=="TrainStop" then clearTrainingOffers()
        elseif kind=="AutoSold" then recordNativeAutoSold(data) end
    end)
end
end

end)()

factories["features/ThrowResult"] = (function()
-- Adonis TAS module: features/ThrowResult
-- Shared names belong to this session context, never the executor global table.
return function(context)
    setfenv(1, context)
function shouldThrowAgain(shot)
    if not shot.auto or not throwingEnabled() or emergency or not shot.accepted then return false end
    if cycle and (cycle.phase~="throw" or cycle.done+1>=cycle.goal) then return false end
    -- Do not starve the five-second upgrade checks or a pending inventory sale.
    if config.BuyBar or config.BuyPlot or config.BuySeed or config.AutoSell then return false end
    if config.EquipBest and eligible("equip") then return false end
    local event=find(pg,"ThrowFX","TestAgain")
    return event~=nil and event:IsA("BindableEvent")
end
function finishShot(shot,confirmed,plant,autoSold)
    if shot~=currentShot then return end
    currentShot=nil
    releasePresentation()
    if confirmed then
        throwFault=nil;throwRetry=nil;throwRejectCount=0
        if shot.auto then
            successCount=successCount+1
            if cycle and shot.cycle==cycle then cycle.done=cycle.done+1 end
            if config.EquipBest and plant then equipDue=equipDue+1 end
        end
        if autoSold then
            log("Throw confirmed by native AutoSold + Collect + idle + Sync; cash="..tostring(shot.autoSold.cash))
        else log("Throw confirmed by response + idle + unique new plant "..tostring(plant.id)) end
        if plant and notifyPlant then
            local ok,err=pcall(notifyPlant,plant)
            if not ok then log("Plant receipt: "..tostring(err)) end
        end
    else
        if shot.auto then
            throwRejectCount=(throwRejectCount or 0)+1
            -- A definite nil plus verified native cleanup permits ONE fresh
            -- Aim retry. Never turn a timeout/transport error into a retry.
            if shot.emptyReply and not shot.extra and not shot.ambiguous
                and shot.aim and (shot.aim==nativeAim or shot.cleanupAim==nativeAim)
                and shot.generation==cancellation
                and not emergency and throwingEnabled() and throwRejectCount<=1 then
                throwRetry={aim=shot.aim,generation=cancellation}
                throwFault=nil;defer("throw",2)
                log("Throw nil cleaned by native game; queue one fresh-Aim retry; services remain deferred")
                return
            end
            throwFault="Phan hoi Throw khong hop le ("..(shot.emptyReply and "nil" or "loi phan hoi")
                .."). Tam dung tele/tu dong; tat va bat lai Loop hoac Auto Throw de thu lai."
            setStatus(throwFault,10)
        end
        log("Throw rejected; native controls restored; no success, no recovery teleport, no automatic retry")
    end
end
function observeShot()
    local shot=currentShot
    if not shot then return end
    local phase=throwPhase()
    -- Handle a finished rejection BEFORE waiting for idle. The updated client
    -- can remain in aiming after a nil reply, so the old ordering deadlocked.
    if shot.done and shot.rejected then
        if not shot.rejectionReported then
            shot.rejectionReported=true
            log("Throw rejected; waiting for native cleanup, not a plant or success")
        end
        if phase=="idle" and nativeControlReady() then finishShot(shot,false);return end
        -- A slow client may miss the short idle window after native abort.
        -- The same native controller starting a NEW Aim also proves cleanup;
        -- the retry fence still forbids upgrades/teleports into other services.
        if shot.recoveryAborted and phase=="aiming" and nativeAim and nativeAim~=shot.aim
            and nativeAim.forwarded then
            shot.cleanupAim=nativeAim;finishShot(shot,false);return
        end
        if shot.auto and shot.emptyReply and not shot.extra and not shot.ambiguous
            and not emergency and shot.generation==cancellation
            and shot.aim==nativeAim and phase=="aiming" and os.clock()-shot.started>=2
            and not shot.cancelTried then
            shot.cancelTried=true
            local fn=shot.abortNative or (captureThrowAbort and captureThrowAbort())
            if fn then
                local ok,err=pcall(fn)
                shot.recoveryAborted=ok
                log("Rejected Throw native abort: "..tostring(ok)..(not ok and (" / "..tostring(err)) or ""))
                resetNativeControl()
            else log("Rejected Throw: native abort unavailable; use the game's movement/cancel control") end
        end
        if not emergency then
            setStatus("Throw "..(shot.emptyReply and "nil" or "error")..": cho game huy luot; chua tele / chua dem thanh cong")
        end
        return
    end
    if phase=="result" then shot.sawResult=true end
    if phase=="result" and shot.auto and not emergency and shot.accepted and not shot.continued then
        -- Only fire when the real Continue prompt exists or phase is verified.
        shot.continueMode=shouldThrowAgain(shot) and "again" or "back"
        local ok,err=continueThrow(shot.continueMode=="again")
        if ok then shot.continued=true else setStatus("Continue: "..tostring(err),8) end
    end
    -- THROW AGAIN collects the previous plant then enters the next native Aim
    -- without idle. Keep the shot lock until Collect + new Aim + fresh Sync
    -- and inventory/AutoSold prove the old result. No new Throw is sent early.
    local nextAim=shot.continueMode=="again" and shot.collectObserved and phase=="aiming"
        and shot.aim and nativeAim and nativeAim~=shot.aim and nativeAim.forwarded
    if not shot.done or (not nextAim and (phase~="idle" or not nativeControlReady())) then
        if os.clock()-shot.started>30 and not emergency then
            setStatus("Cho game: "..tostring(phase).."; xem ThrowReply JSON neu phan hoi loi")
        end
        return
    end
    local _,_,r=character()
    if not r or (r.Anchored and not nextAim) then return end
    if not shot.accepted then
        if not emergency then setStatus("Phan hoi Throw chua dung schema; gui ThrowReply JSON",8) end
        return
    end
    if not shot.before or shot.ambiguous then
        if not emergency then setStatus("Ket qua nem chua du bang chung; dang giu de tranh nem lap") end
        return
    end
    if syncGeneration<=shot.preSync then
        if not emergency then setStatus("Cho Sync cay moi sau nem") end
        return
    end
    local view=inventoryView();if not view then return end
    local newPlants={}
    for id,plant in pairs(view.all) do if not shot.before[id] then newPlants[#newPlants+1]=plant end end
    local sold=shot.autoSold
    if #newPlants==0 and sold and shot.collectObserved
        and shot.response.isNew==false and shot.response.mutation==1
        and sold.plant==shot.response.plant and sold.rarity==shot.response.rarity then
        -- The native game sold this result directly. There is no plant ID or
        -- inventory item to invent, equip or show as a received plant.
        finishShot(shot,true,nil,true);return
    end
    local match=#newPlants==1 and newPlants[1].plant==shot.response.plant
    if match then
        for _,key in ipairs({"id","rarity","mutation","size"}) do
            if shot.response[key]~=nil and newPlants[1][key]~=shot.response[key] then match=false end
        end
    end
    if match then
        finishShot(shot,true,newPlants[1])
    elseif not emergency then setStatus("Cay moi chua khop ket qua nem; cho dong bo") end
end
end

end)()

factories["features/Upgrades"] = (function()
-- Adonis TAS module: features/Upgrades
-- Shared names belong to this session context, never the executor global table.
return function(context)
    setfenv(1, context)
function affordable(price)
    local money=player:GetAttribute("Money")
    return type(price)=="number" and price>=0 and type(money)=="number" and money>=price
end
function eligible(key) return not backoff[key] or os.clock()>=backoff[key] end
function defer(key,seconds) backoff[key]=os.clock()+(seconds or 30) end
function inFlightBatch() return cycle and cycle.phase=="throw" and cycle.done<cycle.goal end
function buyBar()
    if not config.BuyBar or not eligible("bar") then return end
    defer("bar",5)
    if not Balance then return end
    local level=player:GetAttribute("Bar")
    local item=type(level)=="number" and Balance.Bars and Balance.Bars[level+1]
    if not item or not affordable(item.price) then return end
    if not stopTraining() then return end
    local target=find(myPlot(),"BarStation","TrainPad")
    if not target or not teleportNear(target.Position,7,function() return config.BuyBar end) then return end
    level=player:GetAttribute("Bar")
    item=type(level)=="number" and Balance.Bars[level+1]
    if not config.BuyBar or not item or not affordable(item.price) then return end
    local ok=call("BuyBar")
    local deadline=os.clock()+5
    while alive and ok and player:GetAttribute("Bar")==level and os.clock()<deadline do task.wait(0.1) end
    local actual=player:GetAttribute("Bar")
    if type(actual)=="number" and actual>level then log("Training bar upgrade confirmed") end
end
function plotInfo()
    if not readyData() or not Balance or type(Balance.CapacityCost)~="function" then return end
    local base=State.capacityBase or State.capacity
    if type(base)~="number" or type(Balance.CapacityMax)~="number" then return end
    local ok,price=pcall(Balance.CapacityCost,base)
    if not ok or type(price)~="number" then return end
    return base,price,base>=Balance.CapacityMax
end
function buyPlot(checkAfterBatch)
    local base,price,maxed=plotInfo()
    if not base then return end
    if plotCheckpoint and (base>plotCheckpoint.base or maxed) then
        log("Plot checkpoint confirmed");plotCheckpoint=nil;return
    end
    -- This receipt only fences another plot purchase. A delayed Sync must
    -- never freeze training/throwing or be erased by an OFF/ON toggle.
    if plotCheckpoint then return end
    if not config.BuyPlot then return end
    if not eligible("plot") then return end
    defer("plot",5)
    if maxed then return end
    if not affordable(price) then return end
    if not stopTraining() then return end
    local target=find(myPlot(),"CapacitySign","Board")
    if not target or not teleportNear(target,5,function() return config.BuyPlot end) then return end
    base,price,maxed=plotInfo()
    if not config.BuyPlot or not base or maxed or not affordable(price) then return end
    -- Reserve only the purchase actually being sent, after the bar/seed cost
    -- and the post-teleport affordability check. Never reserve future money.
    local receipt={base=base,started=os.clock()}
    plotCheckpoint=receipt
    local ok,message,rejected,sent=call("BuyCapacity")
    if plotCheckpoint~=receipt then return end
    if rejected or sent==false then
        plotCheckpoint=nil
        log("Plot purchase not accepted: "..tostring(message));return
    end
    receipt.ack=ok
    local deadline=os.clock()+5
    while alive and os.clock()<deadline do
        local actual,_,atMax=plotInfo()
        if actual and (actual>base or atMax) then
            if plotCheckpoint==receipt then plotCheckpoint=nil end
            log("Plot capacity upgrade confirmed");return
        end
        task.wait(0.1)
    end
    if plotCheckpoint==receipt then log("Plot purchase awaits capacity Sync; only another plot purchase is deferred") end
end
function buySeed()
    if not config.BuySeed or not eligible("seed") then return end
    defer("seed",5)
    if not Balance or not readyData() then return end
    local current=player:GetAttribute("Seed")
    local nextIndex=type(current)=="number" and current+1
    local item=nextIndex and Balance.Seeds and Balance.Seeds[nextIndex]
    if not item or item.hidden or item.robux or not affordable(item.price) then return end
    if not stopTraining() then return end
    local target=find(myPlot(),"FoodStall","Counter")
    if not target or not teleportNear(target,6,function() return config.BuySeed end) then return end
    if not config.BuySeed or player:GetAttribute("Seed")~=current or not affordable(item.price) then return end
    local owned=false
    for _,index in ipairs(State.seeds or {}) do if index==nextIndex then owned=true end end
    local ok=true
    if not owned then ok=call("BuySeed",{i=nextIndex}) end
    if not ok or emergency then return end
    local deadline=os.clock()+6
    repeat
        owned=false
        for _,index in ipairs(State.seeds or {}) do if index==nextIndex then owned=true end end
        if owned then break end
        task.wait(0.1)
    until not alive or os.clock()>deadline
    if not owned then setStatus("Cho xac nhan so huu hat moi");return end
    if player:GetAttribute("Seed")~=nextIndex and config.BuySeed then call("EquipSeed",{i=nextIndex}) end
    if player:GetAttribute("Seed")==nextIndex then
        log("Next seed purchase and equipment confirmed: "..item.name)
    end
end
end

end)()

factories["features/EquipBest"] = (function()
-- Adonis TAS module: features/EquipBest
-- Shared names belong to this session context, never the executor global table.
return function(context)
    setfenv(1, context)
function equipBest()
    if not config.EquipBest or equipDue<=0 or not eligible("equip") or not readyData() then return end
    if not stopTraining() then return end
    if not config.EquipBest or emergency or not alive then return end
    defer("equip")
    local served=equipDue
    local ok=call("PlaceBest")
    -- One PlaceBest covers ALL plants currently queued. Preserve only tokens
    -- added during the yielding request, rather than replaying old work.
    if ok then equipDue=math.max(0,equipDue-served) end
end
end

end)()

factories["features/AutoSell"] = (function()
-- Adonis TAS module: features/AutoSell
-- Shared names belong to this session context, never the executor global table.
return function(context)
    setfenv(1, context)
function checkSale()
    if not salePending then return true end
    if not salePending.ack then
        setStatus("Ban chua co phan hoi thanh cong; khong tu gui lai");return false
    end
    if syncGeneration<=salePending.sync then setStatus("Cho Sync sau SellStored");return false end
    local view=inventoryView();if not view then return false end
    for id in pairs(salePending.ids) do if view.all[id] then setStatus("Cho danh sach cay sau ban");return false end end
    for id,plant in pairs(salePending.before) do
        if plant.placed and not view.all[id] then setStatus("Du lieu cay vuon thay doi, can kiem tra");return false end
    end
    log("Sell confirmed: "..salePending.count.." stored plants; native ACK + Sync")
    salePending=nil;return true
end
function sellStored()
    if not config.AutoSell or not eligible("sell") or not readyData() then return end
    local view=inventoryView()
    if not view or view.count<config.SellThreshold or view.protected or not noHolding(view) then return end
    if not stopTraining() then return end
    local map=workspace:FindFirstChild("Map")
    local target
    for _,object in ipairs(map and map:GetDescendants() or {}) do
        if object.Name=="Demicercle" and object:GetAttribute("Kind")=="Sell" then
            local center=object:GetAttribute("Center")
            if typeof(center)=="Vector3" then target=center;break end
        end
    end
    if not target then setStatus("Chua tim thay Sell pad");return end
    if not teleportNear(target,3,function() return config.AutoSell end) then return end
    view=inventoryView()
    if not config.AutoSell or not view or view.count<config.SellThreshold or view.protected or not noHolding(view) then return end
    defer("sell")
    salePending={ids=view.stored,before=view.all,count=view.count,sync=syncGeneration}
    local ok,message,rejected,sent=call("SellStored")
    if not salePending then return end
    salePending.ack=ok
    if rejected or sent==false then
        log("SellStored not accepted/sent; retry after cooldown: "..tostring(message))
        salePending=nil;return
    end
    if not ok then
        -- A transport/native rejection is not evidence that nothing was sold.
        salePending.error=tostring(message)
    end
    checkSale()
end
end

end)()

factories["features/ItemBoost"] = (function()
-- Adonis TAS module: features/ItemBoost
-- Native GameUI UseItem {key}; inventory and remaining boosts from ItemsProbe/3.
return function(context)
    setfenv(1, context)
local kinds={"Luck5","Luck2","Money","Train","Lucky10","Lucky"}
local supported={Luck2=true,Luck5=true,Money=true,Train=true,Lucky=true,Lucky10=true}
local pending,retryAt={},{}
local nextUse,cachedRaw,cachedItems=0,nil,nil
local function number(value)
    local n=tonumber(value)
    return n and n==n and n>=0 and n<math.huge and n or nil
end
local function activeAttribute(kind)
    if kind=="Lucky" then return "LuckyThrows" end
    if kind=="Lucky10" then return "LuckyThrows10" end
    return "Boost_"..kind
end
local function active(kind)
    return number(player:GetAttribute(activeAttribute(kind)))
end
local function inventory()
    local raw=player:GetAttribute("Items")
    if type(raw)~="string" or #raw>1000000 then return nil end
    if raw==cachedRaw then return cachedItems end
    cachedRaw,cachedItems=raw,nil
    local ok,data=pcall(Http.JSONDecode,Http,raw)
    if not ok or type(data)~="table" then return nil end
    local result={}
    for key,value in pairs(data) do
        local amount=number(value)
        if type(key)=="string" and amount and amount%1==0 then result[key]=amount end
    end
    cachedItems=result;return result
end
local function parseKey(key)
    if key=="Lucky" or key=="Lucky10" then return key,0 end
    local kind,seconds=key:match("^(%w+):(%d+)$")
    seconds=number(seconds)
    if supported[kind] and kind~="Lucky" and kind~="Lucky10" and seconds and seconds>0 then return kind,seconds end
end
local function grouped(items)
    local groups={}
    for _,kind in ipairs(kinds) do groups[kind]={owned=0,variants={},active=active(kind),pending=pending[kind]~=nil} end
    local total=0
    for key,amount in pairs(items or {}) do
        if amount>0 then
            total=total+amount
            local kind,seconds=parseKey(key)
            if kind then
                local group=groups[kind];group.owned=group.owned+amount
                group.variants[#group.variants+1]={key=key,seconds=seconds,count=amount}
            end
        end
    end
    for _,group in pairs(groups) do
        table.sort(group.variants,function(a,b)
            if a.seconds~=b.seconds then return a.seconds<b.seconds end
            return a.key<b.key
        end)
    end
    return groups,total
end
-- Record attribute evidence even while an accepted charge is consumed by a
-- quick throw, or while the RPC is still yielding. No native UI is touched.
for _,kind in ipairs(kinds) do
    local itemKind=kind
    connect(player:GetAttributeChangedSignal(activeAttribute(kind)),function()
        local receipt=pending[itemKind]
        local value=active(itemKind)
        if receipt and value and value>receipt.beforeActive then receipt.effectSeen=true end
    end)
end
local function reconcile(items)
    if not items then return end
    for kind,receipt in pairs(pending) do
        local value=active(kind)
        if value and value>receipt.beforeActive then receipt.effectSeen=true end
        local remaining=items[receipt.key] or 0
        if remaining<receipt.beforeCount and receipt.effectSeen then
            pending[kind]=nil
            log("UseItem "..receipt.key..": inventory + boost confirmed")
        end
    end
end
function itemBoostView()
    local items=inventory()
    reconcile(items)
    local groups,total=grouped(items)
    return {ready=items~=nil,total=total,groups=groups}
end
local function allowed(kind,groups)
    local group=groups[kind]
    if not config["AutoUse"..kind] or not group or group.owned<1 or group.active==nil
        or pending[kind] or (retryAt[kind] or 0)>os.clock() then return false end
    -- Selected potions may add duration while active. Each use still waits for
    -- the native inventory decrement AND increased timer before sending more.
    -- Keep only one queued Lucky Throw; exhaust selected 10x stock first.
    if kind=="Lucky" or kind=="Lucky10" then
        if groups.Lucky.active==nil or groups.Lucky10.active==nil
            or groups.Lucky.active>0 or groups.Lucky10.active>0 or pending.Lucky or pending.Lucky10 then return false end
        if kind=="Lucky" and config.AutoUseLucky10 and groups.Lucky10.owned>0 then return false end
    end
    return true
end
function serviceItemBoost(fromCoordinator)
    local items=inventory()
    reconcile(items)
    if not initialized or not alive or emergency or throwFault or throwRetry
        or (coordinatorActive and not fromCoordinator) or currentShot or pendingIntent
        or outstanding or env.__AdonisTASOutstanding or busyGame() or not readyData()
        or not items or os.clock()<nextUse then return false end
    local groups=grouped(items)
    for _,kind in ipairs(kinds) do
        if allowed(kind,groups) then
            local candidate=groups[kind].variants[1]
            local receipt={key=candidate.key,beforeCount=items[candidate.key],beforeActive=groups[kind].active,effectSeen=false}
            pending[kind]=receipt
            local accepted,message,rejected,sent=call("UseItem",{key=candidate.key})
            if not sent then
                if pending[kind]==receipt then pending[kind]=nil end
                return false
            end
            nextUse=os.clock()+1.5
            if rejected then
                if pending[kind]==receipt then pending[kind]=nil end
                retryAt[kind]=os.clock()+30
                log("UseItem "..candidate.key..": rejected / "..tostring(message))
            elseif accepted then log("UseItem "..candidate.key..": accepted; waiting for inventory/boost")
            else log("UseItem "..candidate.key..": unknown outcome; waiting for inventory/boost, no resend") end
            reconcile(inventory())
            return true
        end
    end
    return false
end
end

end)()

factories["features/Rewards"] = (function()
-- Adonis TAS module: features/Rewards
-- Native Reward/Settings contracts from the supplied client; no UI activation.
return function(context)
    setfenv(1, context)
local gifts,daily,codes={},{},{}
local giftSession,nextRequest,missingCodes=nil,0,false
local function finite(value)
    local n=tonumber(value)
    return n and n==n and math.abs(n)<math.huge and n or nil
end
local function claimedGifts()
    local result={}
    for index in tostring(player:GetAttribute("GiftsClaimed") or ""):gmatch("%d+") do result[tonumber(index)]=true end
    return result
end
local function codeList()
    local result,seen={},{}
    local function add(code)
        if type(code)~="string" then return end
        code=code:gsub("%s",""):upper()
        if code=="" or #code>100 or seen[code] then return end
        seen[code]=true;result[#result+1]=code
    end
    for _,code in ipairs(REDEEM_CODES or {}) do add(code) end
    local catalog={}
    for key,value in pairs(Balance and type(Balance.Codes)=="table" and Balance.Codes or {}) do
        if type(key)=="string" and (type(value)=="table" or value==true) then catalog[#catalog+1]=key
        elseif type(key)=="number" and type(value)=="string" then catalog[#catalog+1]=value end
    end
    table.sort(catalog)
    for _,code in ipairs(catalog) do add(code) end
    return result
end
local function dispatch(key,action,args,ledger,id)
    -- Last check before reserving the shared request slot; no movement or UI.
    if not alive or emergency or not config[key] then return false end
    local accepted,message,rejected,sent=call(action,args)
    if not sent then return false end
    nextRequest=os.clock()+1.5
    if action=="RedeemCode" then
        -- Even an unknown transport result is attempted only once per session.
        ledger[id]={done=true}
    elseif accepted or not rejected then
        -- Wait for native attributes after accepted/uncertain results; do not
        -- send a duplicate claim while replication is late.
        ledger[id]={pending=true,accepted=accepted==true}
    else ledger[id]={retryAt=os.clock()+30} end
    if accepted then log("Reward "..action.." "..tostring(id)..": accepted")
    elseif rejected then log("Reward "..action.." "..tostring(id)..": "..tostring(message))
    else log("Reward "..action.." "..tostring(id)..": unknown result; no automatic resend") end
    return true
end
function serviceRewards(fromCoordinator)
    if not initialized or not alive or emergency or throwFault or throwRetry
        or (coordinatorActive and not fromCoordinator)
        or outstanding or env.__AdonisTASOutstanding or currentShot or pendingIntent
        or busyGame() or not readyData() then return false end
    local start=finite(player:GetAttribute("SessionStart"))
    if start~=giftSession then gifts={};giftSession=start end
    local claimed=claimedGifts()
    for index,receipt in pairs(gifts) do
        if receipt.pending and claimed[index] then
            gifts[index]={done=true};log("Reward ClaimGift "..index..": GiftsClaimed confirmed")
        end
    end
    local dailyReady=player:GetAttribute("DailyReady")==true
    if not dailyReady then
        if daily.pending then log("Reward ClaimDaily: DailyReady cleared") end
        daily={}
    end
    local now=os.clock()
    if now<nextRequest then return false end
    if config.AutoClaimDaily and dailyReady and not daily.pending and (daily.retryAt or 0)<=now then
        -- ClaimDaily has no day/clock override; the server chooses the reward.
        local ledger={claim=daily}
        local sent=dispatch("AutoClaimDaily","ClaimDaily",{},ledger,"claim")
        daily=ledger.claim
        return sent
    end
    if config.AutoClaimFreeGift and start and Balance and type(Balance.Gifts)=="table" then
        local ok,serverNow=pcall(workspace.GetServerTimeNow,workspace)
        serverNow=ok and finite(serverNow) or nil
        if serverNow and serverNow>=start then
            for index,gift in ipairs(Balance.Gifts) do
                local at=type(gift)=="table" and finite(gift.at)
                local receipt=gifts[index]
                if at and at>=0 and serverNow-start>=at-1 and not claimed[index]
                    and (not receipt or (not receipt.pending and not receipt.done and (receipt.retryAt or 0)<=now)) then
                    return dispatch("AutoClaimFreeGift","ClaimGift",{i=index},gifts,index)
                end
            end
        end
    end
    if config.AutoRedeemCode then
        local list=codeList()
        if #list==0 and not missingCodes then
            log("Auto Redeem: no code list; send your codes to add them")
            missingCodes=true
        end
        for _,code in ipairs(list) do
            if not codes[code] then return dispatch("AutoRedeemCode","RedeemCode",{code=code},codes,code) end
        end
    end
    return false
end
end

end)()

factories["core/Coordinator"] = (function()
-- Adonis TAS module: core/Coordinator
-- Shared names belong to this session context, never the executor global table.
return function(context)
    setfenv(1, context)
function service(checkAfterBatch)
    if emergency or throwFault or busyGame() or outstanding then return end
    if not checkSale() then return end
    equipBest()
    if emergency or busyGame() or outstanding then return end
    if inFlightBatch() then return end
    sellStored()
end

-- Each enabled upgrade owns a five-second scan clock. Due work waits until
-- the native throw and its camera/HUD cleanup have fully released control.
function scanUpgrades(checkAfterBatch)
    if salePending or emergency or throwFault or throwRetry or busyGame() or outstanding then return end
    local generation=cancellation
    buyBar()
    if cancellation~=generation or emergency or busyGame() or outstanding then return end
    buyPlot(checkAfterBatch)
    if cancellation~=generation or emergency or busyGame() or outstanding then return end
    buySeed()
end

ownsTraining,postBatchCheck,lastApproach,lastService=false,false,0,0
function desiredMode()
    if config.Loop then return "loop" end
    if config.AutoTrain and config.AutoThrow then return "combined" end
end
function throwingEnabled() return config.Loop or config.AutoThrow end
function makeCycle(mode,phase)
    cycleSerial=cycleSerial+1
    return {id=cycleSerial,mode=mode,phase=phase or "train",seconds=config.TrainingTime,
        goal=config.ThrowsPerTurn,done=0}
end
function atPerfect()
    local gauge=find(pg,"HudLancer","Jauge")
    if not visible(gauge) then return false end
    local cursor=find(gauge,"Capsule","Curseur")
    local bonus=cursor and cursor:FindFirstChild("Bonus")
    if not cursor or not bonus or bonus.Text~="+20" or not Balance then return false end
    -- Exact formula from the supplied ThrowClient and its live Balance module.
    local raw=(317-cursor.Position.Y.Offset)/304
    local band=Balance.PerfectBand
    return type(band)=="number" and raw>=math.max(1-band,0.99) and raw<=1.01
end
function submitAtPerfect()
    if not initialized or coordinatorActive or emergency or throwFault or not throwingEnabled()
        or currentShot or pendingIntent or outstanding or env.__AdonisTASOutstanding then return end
    if throwRetry and (throwRetry.generation~=cancellation or nativeAim==throwRetry.aim) then return end
    if not eligible("throw") then return end
    -- Use the first near-maximum peak (~0.73s). Keep the >=0.99 power check,
    -- rather than tapping the early +20 edge (~0.64s) seen in rejected logs.
    if not nativeAim or not nativeAim.forwarded or nativeAim.consumed
        or os.clock()-nativeAim.time<0.7 then return end
    if not throwInputOK or not observerOK or throwPhase()~="aiming" or not atPerfect() or not readyData() then return end
    local mode=desiredMode()
    if mode and (not cycle or cycle.mode~=mode) then cycle=makeCycle(mode,"throw") end
    if cycle and cycle.phase~="throw" then cycle.phase="throw" end
    setShotPresentation({fast=config.FastThrow})
    pendingIntent={time=os.clock(),generation=cancellation,cycle=cycle,
        abortNative=captureThrowAbort and captureThrowAbort()}
    log("Power bar PERFECT; using the game's throw input event")
    throwEvent:Fire()
end
function approachThrow()
    if throwFault then return end
    if not observerOK or not throwInputOK then setStatus("Volt chua mo du API dieu khien/quan sat nem");return end
    if throwPhase()=="aiming" then setStatus("Can thanh luc +20");return end
    if throwPhase()~="idle" or currentShot or outstanding then return end
    if os.clock()-lastApproach<2.5 then return end
    if not stopTraining() then return end
    lastApproach=os.clock()
    local strip=find(workspace,"Map","Canyon","LaunchStrip")
    if not strip then setStatus("Cho LaunchStrip stream vao client");return end
    setStatus("Tele den vach nem")
    -- Arrive on the hub side first, outside the native auto-aim trigger. The
    -- game must have a chance to replicate this move before anchoring on Aim.
    local generation=cancellation
    local guard=function()return throwingEnabled() and cancellation==generation end
    local _,_,root=character()
    if not root then return end
    if (root.Position-strip.Position).Magnitude>16 then
        local staging=strip.CFrame:PointToWorldSpace(Vector3.new(0,0,strip.Size.Z*0.5+4))
        if not teleportNear(staging,2.5,guard) then return end
        task.wait(0.8)
    end
    if not activityValid(generation,guard) or busyGame() then return end
    teleportNear(strip.Position,2.5,guard)
end
function autoStep()
    if not initialized then return end
    observeShot()
    if outstanding or currentShot then return end
    if pendingIntent then
        if os.clock()-pendingIntent.time>3 then
            pendingIntent=nil
            releasePresentation()
            throwFault="Khong quan sat duoc request Throw. Tam dung tele/tu dong; tat va bat lai Loop hoac Auto Throw de thu lai."
            log(throwFault)
        end
        return
    end
    if emergency then return end
    if throwFault then setStatus(throwFault);return end
    if env.__AdonisTASOutstanding then setStatus("Cho request cua phien truoc hoan tat");return end
    if not readyData() then setStatus("Cho ClientState.ready / Sync");return end
    if throwRetry then
        if throwRetry.generation~=cancellation or not throwingEnabled() then throwRetry=nil
        else
            -- Resume the interrupted throw, never visit upgrade/train/sell
            -- stations between its rejection and the single fresh-Aim retry.
            if eligible("throw") then approachThrow() end
            return
        end
    end
    if not checkSale() then return end
    local stepGeneration=cancellation
    local mode=desiredMode()
    if cycle and cycle.mode~=mode then cycle=nil end
    if busyGame() then
        if throwPhase()=="aiming" and throwingEnabled() then setStatus("Can thanh luc +20")
        else setStatus("Nhuong luot nem / camera cua game") end
        return
    end
    if serviceItemBoost and serviceItemBoost(true) then return end
    if serviceRewards and serviceRewards(true) then return end
    if cycle and cycle.phase=="throw" and cycle.done>=cycle.goal then
        cycle.phase="service";postBatchCheck=true
        log("Batch complete: "..cycle.done.."/"..cycle.goal)
    end
    scanUpgrades(postBatchCheck)
    if cancellation~=stepGeneration or not alive or salePending or outstanding or emergency or busyGame() then return end
    if not inFlightBatch() and os.clock()-lastService>1 then
        lastService=os.clock();service(postBatchCheck)
        if cancellation~=stepGeneration or not alive or salePending or outstanding or emergency or busyGame() then return end
        postBatchCheck=false
        if cycle and cycle.phase=="service" then cycle=nil end
    elseif equipDue>0 and config.EquipBest then equipBest() end
    if cycle and cycle.phase=="service" then return end
    if mode and not cycle then cycle=makeCycle(mode) end
    if cycle then
        local activeCycle=cycle
        if cycle.phase=="train" then
            if (cycle.deadline and os.clock()>=cycle.deadline)
                or (cycle.remaining~=nil and cycle.remaining<=0) then
                if stopTraining() and cycle==activeCycle and not emergency then cycle.phase="throw";ownsTraining=false end
                return
            end
            setStatus("Luyen: "..(cycle.deadline and tostring(math.max(0,math.ceil(cycle.deadline-os.clock()))) or tostring(cycle.seconds)).."s")
            if startTraining(function() return cycle==activeCycle and desiredMode()==mode end)
                and cycle==activeCycle and not emergency then
                ownsTraining=true
                if not cycle.deadline then cycle.deadline=os.clock()+(cycle.remaining or cycle.seconds) end
            end
        elseif cycle.done>=cycle.goal then
            log("Batch complete: "..cycle.done.."/"..cycle.goal)
            cycle=nil;postBatchCheck=true
        elseif eligible("throw") then
            setStatus("Nem "..(cycle.done+1).."/"..cycle.goal)
            approachThrow()
        end
    elseif config.AutoThrow and eligible("throw") then approachThrow()
    elseif config.AutoTrain then
        setStatus("Auto Train")
        if startTraining(function() return config.AutoTrain and not config.Loop end) then ownsTraining=true end
    elseif ownsTraining and training() then
        stopTraining();ownsTraining=false
    else setStatus("San sang - bat tung chuc nang de chay") end
end

automationKeys={"Loop","AutoTrain","AutoTap","AutoThrow","EquipBest","BuyBar","BuyPlot","BuySeed","AutoSell",
    "AutoClaimFreeGift","AutoClaimDaily","AutoRedeemCode",
    "AutoUseLuck2","AutoUseLuck5","AutoUseMoney","AutoUseTrain","AutoUseLucky","AutoUseLucky10"}
function emergencyStop()
    cancellation=cancellation+1
    emergency=true;cycle=nil;throwRetry=nil;pendingIntent=nil;equipDue=0;postBatchCheck=false
    if not currentShot then releasePresentation() end
    stickyStatus,stickyUntil=nil,nil
    for _,key in ipairs(automationKeys) do config[key]=false end
    configRevision=configRevision+1;configDirty=config.AutoSave
    setStatus("DA DUNG - luot game da nhan van do game hoan tat")
    if not currentShot and not outstanding and training() then spawn(stopTraining) end
    if refreshUI then refreshUI() end
end
setOption=function(key,value)
    if defaults[key]==nil then return end
    if numericLimits[key] then
        value=tonumber(value);local range=numericLimits[key]
        if not value or value~=value then return end
        value=math.max(range[1],math.min(range[2],math.floor(value)))
    elseif type(value)~="boolean" then return end
    if config[key]==value then return end
    if (key=="Loop" or key=="AutoThrow") and value and (not throwInputOK or not observerOK) then
        setStatus("Auto Throw: cho ThrowFX.TestTap / observer. Gui log neu van thieu.",8)
        return
    end
    config[key]=value
    if (key=="Loop" or key=="AutoThrow") and value then
        throwFault=nil;throwRetry=nil;throwRejectCount=0;backoff.throw=nil
        stickyStatus,stickyUntil=nil,nil
        resetNativeControl()
    end
    configRevision=configRevision+1
    configDirty=config.AutoSave
    if key=="AutoSave" and not value then configDirty=false end
    if key=="AutoSave" and value then configDirty=true end
    if key=="Loop" or key=="AutoTrain" or key=="AutoThrow" then
        cancellation=cancellation+1
        if not config.Loop and key=="Loop" then cycle=nil end
    end
    if key=="EquipBest" then equipDue=value and 1 or 0;backoff.equip=nil end
    if value and key=="BuyBar" then backoff.bar=nil end
    if value and key=="BuyPlot" then backoff.plot=nil end
    if value and key=="BuySeed" then backoff.seed=nil end
    if key=="BoostFPS" then applyFPS() end
    if key=="HideMyPlants" then applyMyPlants() end
    -- Visual/preferences changes after End must not resume an old throw.
    if value==true then
        for _,automationKey in ipairs(automationKeys) do
            if key==automationKey then emergency=false;break end
        end
    end
    log("Option "..key.." = "..tostring(value))
    if refreshUI then refreshUI() end
end
end

end)()

