local initializeArtwork=(function()
-- Generated artwork payloads. Edit assets/, then python tools/build-branding.py.
-- Local executor asset support is optional; no HTTP request or remote asset ID.
return function(ctx)
local register=type(getcustomasset)=="function" and getcustomasset
    or (type(getsynasset)=="function" and getsynasset)
ctx.brandLogo,ctx.brandArt="",""
if not register or type(writefile)~="function" then return end
local function loadAsset(filename,payload)
local path=ctx.dataPath(filename)
local ok,uri=pcall(function()
    assert(ctx.ensureDataFolder(),"Executor cannot create/access logo folder")
    local exists=false
    if type(isfile)=="function" then local checked,value=pcall(isfile,path); exists=checked and value==true end
    if not exists then
        -- Decode once at initialization, before any automated cinema is active.
        local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local lookup={}; for i=1,#alphabet do lookup[alphabet:sub(i,i)]=i-1 end
        local bytes={}
        for i=1,#payload,4 do
            local a,b,c,d=payload:sub(i,i),payload:sub(i+1,i+1),payload:sub(i+2,i+2),payload:sub(i+3,i+3)
            local n=lookup[a]*262144+lookup[b]*4096+(lookup[c] or 0)*64+(lookup[d] or 0)
            bytes[#bytes+1]=string.char(math.floor(n/65536)%256)
            if c~="=" then bytes[#bytes+1]=string.char(math.floor(n/256)%256) end
            if d~="=" then bytes[#bytes+1]=string.char(n%256) end
        end
        writefile(path,table.concat(bytes))
    end
    return register(path)
end)
if ok and type(uri)=="string" and uri~="" then return uri end
return ""
end
ctx.brandLogo=loadAsset("AdonisHub-logo-cd5cc76175b9.png","")
ctx.brandArt=loadAsset("AdonisHub-ui-art-7fb57836dd8b.png","")
-- Font files share the same bytes with the offline renderer.
local function loadFont(key,name,filename,weight,payload)
    local asset=loadAsset(filename..".ttf",payload)
    if asset=="" then return end
    local ok,family=pcall(function()
        local path=ctx.dataPath(filename..".font.json")
        local data={name=name,faces={{name=weight==700 and "Bold" or "Regular",weight=weight,style="normal",assetId=asset}}}
        writefile(path,game:GetService("HttpService"):JSONEncode(data))
        return register(path)
    end)
    if ok and type(family)=="string" and family~="" then ctx[key]=family end
end
