local initializeUI=(function()
-- Native Adonis shell; actions and saved settings remain in controller.
return function(ctx)
local W,H,SIDE,LEFT,CW=900,600,258,274,610
local MENU_SCALE=0.9
local HEADER_H=56
local PAGE_Y,TITLE_Y=132,88
