local function animate(obj,goals,instant,duration)
    local previous=animations[obj]
    if previous then previous:Cancel(); previous:Destroy(); animations[obj]=nil; animationGoals[obj]=nil end
    -- Controls use immediate visual feedback. Only explicit page transitions
    -- animate, and pointer-held menu dragging also settles those transitions.
    if instant or not duration or (ctx.view.dragState and ctx.view.dragState.active) or not ctx.services.TweenService then
        for key,value in pairs(goals) do obj[key]=value end
    else
        local tween=ctx.services.TweenService:Create(obj,TweenInfo.new(duration or 0.16,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),goals)
        animations[obj],animationGoals[obj]=tween,goals; tween:Play()
    end
end
