local function glyph(parent,index)
    local lines={}
    local navX=({[0]=704,[2]=832})[index]
    if navX and ctx.brandArt and ctx.brandArt~='' then
        local image=Instance.new('ImageLabel',parent)
        image.Name,image.Size,image.BackgroundTransparency,image.Active=index==0 and 'HomeIcon' or 'UpgradeIcon',UDim2.new(1,0,1,0),1,false
        image.Image,image.ImageRectOffset,image.ImageRectSize=ctx.brandArt,Vector2.new(navX,168),Vector2.new(64,64)
        image.ImageColor3,image.ScaleType=C.navText,Enum.ScaleType.Fit
        return lines,image
    end
    if index==3 and ctx.brandArt and ctx.brandArt~='' then
        local image=Instance.new('ImageLabel',parent)
        image.Name,image.Size,image.BackgroundTransparency,image.Active='SellIcon',UDim2.new(1,0,1,0),1,false
        image.Image,image.ImageRectOffset,image.ImageRectSize=ctx.brandArt,Vector2.new(832,96),Vector2.new(64,64)
        image.ImageColor3,image.ScaleType=C.muted,Enum.ScaleType.Fit
        return lines,image
    end
    local function line(x,y,w,h,r)
        local o=frame(parent,x,y,w,h,C.muted)
        if r then o.Rotation=r end
        round(o,1); lines[#lines+1]=o
    end
    if index==0 then
        -- Simple native segments remain a readable asset-free fallback.
        line(1,6,11,2,-40); line(8,6,11,2,40); line(3,9,2,10); line(14,9,2,10); line(3,17,13,2); line(8,12,3,7)
    elseif index==1 then
        line(0,10,3,8); line(7,3,3,15); line(14,7,3,11)
    elseif index==2 then
        line(9,2,2,14); line(3,5,9,2,-45); line(8,5,9,2,45); line(2,18,16,2)
    elseif index==3 then
        line(4,1,10,2); line(13,3,5,2,50); line(16,6,2,6); line(1,7,2,6)
        line(2,14,5,2,50); line(5,17,10,2); line(14,8,5,2,-45); line(0,10,5,2,-45)
        line(8,4,2,12); line(6,5,7,2); line(5,8,7,2,30); line(6,12,7,2)
    elseif index==4 then
        parent.Name="SettingsIcon"
        if ctx.brandGear and ctx.brandGear~="" then
            local image=Instance.new("ImageLabel",parent)
            image.Name,image.Size,image.BackgroundTransparency,image.Active="GearOutline",UDim2.new(1,0,1,0),1,false
            image.Image,image.ImageColor3,image.ScaleType=ctx.brandGear,C.muted,Enum.ScaleType.Fit
            return lines,image
        end
        -- A single thin outline: eight teeth and an open centre. Every segment
        -- participates in the same hover/toggle colour changes as other glyphs.
        local points={}
        for tooth=0,7 do
            for _,p in ipairs({{-22.5,6.8},{-12,6.8},{-9,9},{9,9},{12,6.8}}) do
                local angle=math.rad(tooth*45-90+p[1])
                points[#points+1]={10+math.cos(angle)*p[2],10+math.sin(angle)*p[2]}
            end
        end
        local function segment(a,b)
            local dx,dy=b[1]-a[1],b[2]-a[2]
            local length=math.sqrt(dx*dx+dy*dy)
            line((a[1]+b[1])/2-length/2,(a[2]+b[2])/2-0.7,length,1.4,math.deg(math.atan2(dy,dx)))
        end
        for i,p in ipairs(points) do segment(p,points[i%#points+1]) end
        for i=0,15 do
            local a,b=i*math.pi/8,(i+1)*math.pi/8
            segment({10+math.cos(a)*3.1,10+math.sin(a)*3.1},{10+math.cos(b)*3.1,10+math.sin(b)*3.1})
        end
    elseif index==10 then
        for _,x in ipairs({1,8,15}) do line(x,5,2,14) end
        line(0,9,18,2); line(0,15,18,2); line(8,0,2,5); line(5,2,5,2,-45); line(9,2,5,2,45)
    elseif index==11 or index==8 then
        parent.Name="SproutIcon"
        line(9,7,2,13);round(lines[#lines],1)
        line(0,3,11,7,32);lines[#lines].Name="SproutLeafLeft";round(lines[#lines],4)
        line(10,0,11,7,-32);lines[#lines].Name="SproutLeafRight";round(lines[#lines],4)
    elseif index==5 then
        line(1,9,16,2); line(1,5,3,10); line(14,5,3,10); line(5,3,2,14); line(10,3,2,14)
    elseif index==6 then
        line(7,4,3,13,-18); line(11,10,3,9,35); line(0,7,4,2); line(3,0,2,4); line(13,1,2,4,45)
    elseif index==7 then
        line(1,8,15,2,-30); line(10,3,7,2); line(15,3,2,7); line(2,14,8,2)
    elseif index==9 then
        line(3,3,13,2); line(14,3,2,6); line(12,7,6,2,-45)
        line(2,15,13,2); line(2,10,2,6); line(0,10,6,2,-45)
    elseif index==12 then
        parent.Name="RewardIcon"
        if ctx.brandGift and ctx.brandGift~="" then
            local image=Instance.new("ImageLabel",parent)
            image.Name,image.Size,image.BackgroundTransparency,image.Active="GiftOutline",UDim2.new(1,0,1,0),1,false
            image.Image,image.ImageColor3,image.ScaleType=ctx.brandGift,C.muted,Enum.ScaleType.Fit
            return lines,image
        end
        -- Gift-box outline and two bow loops, in the menu's thin rounded stroke.
        line(1,6,18,1.5); line(1,6,1.5,5); line(17.5,6,1.5,5)
        line(1,10,18,1.5); line(3,11,1.5,8); line(15.5,11,1.5,8)
        line(3,18,14,1.5); line(8.5,6,3,13)
        local loops={{{10,6},{5,5},{4,2},{6,1},{10,6}},{{10,6},{15,5},{16,2},{14,1},{10,6}}}
        for _,points in ipairs(loops) do
            for i=1,#points-1 do
                local a,b=points[i],points[i+1];local dx,dy=b[1]-a[1],b[2]-a[2]
                local length=math.sqrt(dx*dx+dy*dy)
                line((a[1]+b[1])/2-length/2,(a[2]+b[2])/2-0.75,length,1.5,math.deg(math.atan2(dy,dx)))
            end
        end
    elseif index==14 or index==15 then
        local money=index==14
        parent.Name=money and "MoneyBoostIcon" or "LuckBoostIcon"
        local asset=money and ctx.brandMoneyBoost or ctx.brandLuckBoost
        if asset and asset~="" then
            local image=Instance.new("ImageLabel",parent)
            image.Name,image.Size,image.BackgroundTransparency,image.Active=money and "MoneyOutline" or "CloverOutline",UDim2.new(1,0,1,0),1,false
            image.Image,image.ImageColor3,image.ScaleType=asset,C.muted,Enum.ScaleType.Fit
            return lines,image
        end
        if money then
            line(1,6,18,1.5);line(1,6,1.5,12);line(17.5,6,1.5,12);line(1,17,18,1.5)
            line(2,4,14,1.5,-16);line(5,2,10,1.5,-25)
            line(9,8,1.5,8);line(7,9,6,1.5);line(7,12,6,1.5,24);line(7,15,6,1.5)
        else
            local points={{10,5},{7,0},{4,1},{3,4},{0,5},{1,8},{6,10},{1,12},{0,15},{3,17},{4,20},{7,19},{10,14},{13,19},{16,20},{17,17},{20,15},{19,12},{14,10},{19,8},{20,5},{17,4},{16,1},{13,0},{10,5}}
            for i=1,#points-1 do
                local a,b=points[i],points[i+1];local dx,dy=b[1]-a[1],b[2]-a[2]
                local length=math.sqrt(dx*dx+dy*dy)
                line((a[1]+b[1])/2-length/2,(a[2]+b[2])/2-0.7,length,1.4,math.deg(math.atan2(dy,dx)))
            end
            line(9,14,1.5,7,16)
        end
    elseif index==13 then
        parent.Name="PotionIcon"
        if ctx.brandPotion and ctx.brandPotion~="" then
            local image=Instance.new("ImageLabel",parent)
            image.Name,image.Size,image.BackgroundTransparency,image.Active="PotionOutline",UDim2.new(1,0,1,0),1,false
            image.Image,image.ImageColor3,image.ScaleType=ctx.brandPotion,C.muted,Enum.ScaleType.Fit
            return lines,image
        end
        line(7,0,7,1.5);line(8,1,1.5,5);line(11.5,1,1.5,5)
        line(3,8,7,1.5,-45);line(10,8,7,1.5,45)
        line(2,10,1.5,8);line(16.5,10,1.5,8);line(3,18,14,1.5)
        line(3,12,14,1.5);line(6,14,1.5,2)
    else
        for i,x in ipairs({4,11,7}) do line(0,(i-1)*7+3,18,1); line(x,(i-1)*7,3,7) end
    end
    return lines
end
function ctx.selectMenuTab(name,instant)
    if name=="Item Boost" then
        ctx.selectFarmTab(name,instant); return
    end
    if not pages[name] then return end
    local previous=ctx.view.activeTab
    if previous==name and not instant then
        if name=="Home" and ctx.refreshHome then ctx.refreshHome() end
        return
    end
    local direction=previous and navVisuals[previous] and navVisuals[name].index<navVisuals[previous].index and -1 or 1
    ctx.view.activeTab=name; pageTitle.Text=name
    for key,page in pairs(pages) do
        page.Visible=key==name
        animate(page,{Position=UDim2.fromOffset(LEFT,pageY(key))},true)
    end
    for key,v in pairs(navVisuals) do
        local selected=key==name
        animate(navs[key],{BackgroundTransparency=selected and 0.12 or 1},instant)
        animate(v.label,{TextColor3=selected and C.accent or C.navText},instant)
        for _,line in ipairs(v.lines) do animate(line,{BackgroundColor3=selected and C.accent or C.navText},instant) end
