local windowMotion,windowSerial={},0
local windowConnection
local windowRestPosition,windowRestScale=panel.Position or UDim2.fromOffset(0,0),scale.Scale
local function offsetPosition(p,y)
    return UDim2.new(p.X.Scale,p.X.Offset,p.Y.Scale,p.Y.Offset+y)
end
local function cancelWindowMotion()
    windowSerial=windowSerial+1
    if windowConnection then windowConnection:Disconnect(); windowConnection=nil end
    for _,tween in ipairs(windowMotion) do tween:Cancel(); tween:Destroy() end
    windowMotion={}; ctx.view.menuAnimating=false
end
local function finishWindowPose()
    panel.Position,scale.Scale=windowRestPosition,windowRestScale
    panel.Visible=ctx.view.menuOpen
end
function ctx.finishMenuMotion()
    if not ctx.view.menuAnimating then return end
    cancelWindowMotion(); finishWindowPose()
end
function ctx.finishMenuDragMotion()
    ctx.finishMenuMotion()
    -- Settle page/title/marker/hover endpoints before capturing the drag pose.
    -- Subsequent UI updates apply instantly for the entire pointer hold.
    for obj,tween in pairs(animations) do
        tween:Cancel(); tween:Destroy()
        for key,value in pairs(animationGoals[obj]) do obj[key]=value end
    end
    animations,animationGoals={},{}
end
table.insert(ctx.disposers,function() cancelWindowMotion(); ctx.finishLauncherMotion() end)
function ctx.positionLauncher(x,y)
    local camera=workspace.CurrentCamera
    if not camera then return end
    local size=camera.ViewportSize
    reopen.Position=UDim2.fromOffset(math.floor(math.clamp(x,4,math.max(4,size.X-launcherWidth-4))),
        math.floor(math.clamp(y,4,math.max(4,size.Y-launcherHeight-4))))
end
function ctx.setMenuVisible(open,instant)
    if not ctx.state.alive then return end
    open=open==true
    if open==ctx.view.menuOpen then return end
    if not open and ctx.view.dragState then ctx.view.dragState.active=false end
    if ctx.view.launcherDrag then ctx.view.launcherDrag.active=false end
    if not ctx.view.menuAnimating then windowRestPosition,windowRestScale=panel.Position,scale.Scale end
    local wasVisible=panel.Visible
    cancelWindowMotion(); ctx.finishLauncherMotion()
    ctx.view.menuOpen=open; reopen.Visible=not open
    local service=ctx.services.TweenService
    if instant or not service then finishWindowPose()
    else
        panel.Visible=true
        if open and not wasVisible then
            panel.Position=offsetPosition(windowRestPosition,12); scale.Scale=windowRestScale*0.965
        end
        local token=windowSerial
        local ok=pcall(function()
            local seconds=open and 0.24 or 0.17
            local info=TweenInfo.new(seconds,Enum.EasingStyle.Quart,open and Enum.EasingDirection.Out or Enum.EasingDirection.In)
            windowMotion[1]=service:Create(scale,info,{Scale=windowRestScale*(open and 1 or 0.965)})
            windowMotion[2]=service:Create(panel,info,{Position=offsetPosition(windowRestPosition,open and 0 or 12)})
            ctx.view.menuAnimating=true
            windowConnection=windowMotion[2].Completed:Connect(function(playback)
                if playback~=Enum.PlaybackState.Completed or token~=windowSerial or not ctx.state.alive then return end
                cancelWindowMotion(); finishWindowPose()
            end)
            for _,tween in ipairs(windowMotion) do tween:Play() end
            if not open then
                launcherScale.Scale=0.88
                launcherMotion=service:Create(launcherScale,TweenInfo.new(0.24,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{Scale=1})
                launcherMotion:Play()
            end
        end)
        if not ok then cancelWindowMotion(); ctx.finishLauncherMotion(); finishWindowPose() end
    end
    if open and ctx.view.activeTab=="Home" and ctx.refreshHome then ctx.refreshHome() end
end
