local function paintToggle(b,instant)
    local v=ctx.view.toggleVisuals[b]
    local activeColor=Color3.fromRGB(255,255,255)
    animate(b,{BackgroundColor3=v.on and C.on or (v.hovered and C.hover or (v.hero and C.hero or C.card))},instant)
    animate(v.border,{Color=v.on and activeColor or C.line,Transparency=1},instant)
    for _,line in ipairs(v.iconLines) do animate(line,{BackgroundColor3=v.on and activeColor or C.muted},instant) end
    if v.image then animate(v.image,{ImageColor3=v.on and activeColor or C.muted},instant) end
end
function ctx.addToggle(text,description,parent,y,callback,layout)
    local o=layout or {}; local width,height=o.width or CW-8,o.height or 62
    local b=ctx.button(text,o.x or 4,y+2,width,callback,parent,true)
    b.Size=UDim2.fromOffset(width,height); b.BackgroundColor3=description and C.hero or C.card; b.BackgroundTransparency=A.card; round(b,12)
    local border=stroke(b,0.6)
    local hero=o.hero==true
    local titleLines=o.titleLines or 1
    local titleHeight=titleLines==2 and 56 or 30
    local descriptionY=titleLines==2 and 64 or 38
    local tileY=description and 12 or math.floor((height-36)/2)
    local iconTile=frame(b,16,tileY,36,36,C.base); iconTile.BackgroundTransparency=0.35; round(iconTile,11)
    local icon=frame(iconTile,8,8,20,20); icon.BackgroundTransparency=1
    local iconIndex=o.icon or (({['Main Farm']=5,Upgrade=2,['Auto Sell']=3,Setting=4})[parent.Name] or 0)
    if hero then iconIndex=9
    elseif text=='Auto Tap X2' then iconIndex=6
    elseif text=='Equip Best' then iconIndex=8
    elseif text=='Boost FPS' or text=='Auto Save Config' then iconIndex=4 end
    if parent.Name=="Setting" then iconIndex=4 end
    local iconLines,iconImage={}
    local spriteX=({[5]=320,[6]=384,[10]=704,[3]=832})[iconIndex]
    if spriteX and ctx.brandArt and ctx.brandArt~='' then
        iconImage=Instance.new('ImageLabel',iconTile)
        iconImage.Name=({[5]='DumbbellIcon',[6]='TapHandIcon',[10]='PlotIcon',[3]='SellIcon'})[iconIndex]
        iconImage.Position,iconImage.Size=UDim2.fromOffset(4,4),UDim2.fromOffset(28,28)
        iconImage.BackgroundTransparency,iconImage.Active=1,false
        iconImage.Image,iconImage.ImageRectOffset,iconImage.ImageRectSize=ctx.brandArt,Vector2.new(spriteX,96),Vector2.new(64,64)
        iconImage.ImageColor3,iconImage.ScaleType=C.muted,Enum.ScaleType.Fit
    else iconLines,iconImage=glyph(icon,iconIndex) end
    local caption=label(b,text,70,description and 6 or 0,width-156,description and titleHeight or height,22,C.text,true)
    caption.TextWrapped,caption.TextTruncate=true,Enum.TextTruncate.None
    local desc
    if description then
        desc=label(b,description,70,descriptionY,width-92,height-descriptionY-10,14,C.muted)
        desc.TextWrapped,desc.TextTruncate=true,Enum.TextTruncate.None
    end
    local track=frame(b,width-66,description and 12 or math.floor((height-25)/2),46,25,C.off); round(track,12)
    local thumb=frame(track,4,4,17,17,C.text); round(thumb,9)
    ctx.view.toggleVisuals[b]={track=track,thumb=thumb,label=caption,border=border,iconLines=iconLines,image=iconImage,description=desc,hero=hero,on=false,hovered=false}
    connect(b.MouseEnter,function() ctx.view.toggleVisuals[b].hovered=true; paintToggle(b) end)
    connect(b.MouseLeave,function() ctx.view.toggleVisuals[b].hovered=false; paintToggle(b) end)
    return b
end
function ctx.refreshToggle(button,on,instant)
    local v=ctx.view.toggleVisuals[button];on=on==true
    if v.initialized and v.on==on then return end
    instant=instant or not v.initialized
    v.on,v.initialized=on,true
    animate(v.track,{BackgroundColor3=on and C.accent or C.off},instant,0.18)
    animate(v.thumb,{Position=UDim2.fromOffset(on and 25 or 4,4),BackgroundColor3=on and C.base or C.text},instant,0.2)
    paintToggle(button,instant)
end
function ctx.addSection(text,parent,y)
