end
menuUI=createMenu({Player=player,PlayerGui=pg,Values=config,Version=VERSION,
    Keyboard=false,InviteLink=DISCORD_INVITE,AssetFolder=FOLDER.."/assets",RarityNames=names,
    OnToggle=function(key,value) setOption(key,value);if refreshUI then refreshUI() end end,
    OnNumber=function(key,value) setOption(key,value);if refreshUI then refreshUI() end end,
    OnRarity=function(tier,value)applyNativeAutoSell(tier,value);if refreshNativeAutoSellUI then refreshNativeAutoSellUI() end end,
    OnStop=emergencyStop,
    OnHome=function()if DISCORD_INVITE~="" and refreshCommunity then spawn(refreshCommunity) end end,
    OnUnload=function()if controller then controller.destroy("unloaded") end end,
    OnError=function(err)log("Menu action: "..tostring(err),"warning","menu-action")end})
gui,frame,mini=menuUI.Gui,menuUI.Large,menuUI.Compact
pages=menuUI.View.pages
showPage=function(name)return menuUI.SelectTab(name)end
toggleMenu=function()menuUI.Toggle()end
end

