factories["ui/Home"] = (function()
-- Adonis TAS module: ui/Home
-- Community data for the supplied menu; visuals belong to ui/Menu.
return function(context)
    setfenv(1, context)
do
    local nextFetch,fetching=0,false
    refreshCommunity=function()
        if DISCORD_INVITE=="" or fetching or os.clock()<nextFetch then return end
        local code=DISCORD_INVITE:match("discord%.gg/([%w_-]+)") or DISCORD_INVITE:match("discord%.com/invite/([%w_-]+)")
        if not code then menuUI.SetHomeStatus("Discord invite khong hop le");return end
        fetching=true
        local ok,data=pcall(function()
            local url="https://discord.com/api/v10/invites/"..code.."?with_counts=true"
            local requestFn=type(request)=="function" and request or http_request
            local body
            if type(requestFn)=="function" then
                local result=requestFn({Url=url,Method="GET"})
                if type(result)~="table" or result.StatusCode~=200 then error("Discord request failed") end
                body=result.Body
            else body=game:HttpGet(url) end
            local result=Http:JSONDecode(body)
            if not result.guild or type(result.guild.name)~="string" then error("Guild unavailable") end
            return result
        end)
        fetching=false
        if not alive then return end
        if ok then
            nextFetch=os.clock()+300
            menuUI.SetCommunity({Name=data.guild.name,Online=data.approximate_presence_count,Members=data.approximate_member_count})
            menuUI.SetHomeStatus("")
        else nextFetch=os.clock()+30;menuUI.SetHomeStatus("Khong tai duoc thong tin Discord") end
    end
    serviceCommunity=function()
        if DISCORD_INVITE~="" and not fetching and os.clock()>=nextFetch
            and menuUI.View.menuOpen and menuUI.View.activeTab=="Home" then
            spawn(refreshCommunity)
        end
    end
end
if DISCORD_INVITE~="" then spawn(refreshCommunity) end
end

end)()

