factories["ui/PlantReceipt"] = (function()
-- Adonis TAS module: ui/PlantReceipt
-- UI/UX adapted from the receipt supplied by the user; data comes from Throw a Seed.
return function(context)
    setfenv(1, context)
local createPlantReceipt=(function()
return function(playerGui,tweenService)
    playerGui=playerGui or game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
    local ctx={pg=playerGui,services={TweenService=tweenService or game:GetService("TweenService")},
        view={},state={alive=true},disposers={}}
local expiresAt, preview
local TweenService=ctx.services.TweenService
local receiptSerial,tweens,tweenConnections=0,{},{}
local exiting=false
local receiptSeconds,exitSeconds=5,0.2
local receiptScale=1
local gui = Instance.new("ScreenGui")
local cleanupPresentation
table.insert(ctx.disposers,function()
    if cleanupPresentation then cleanupPresentation() else gui:Destroy() end
end)
gui.Name,gui.ResetOnSpawn,gui.IgnoreGuiInset = "AdonisTASPresentation",false,true
gui.DisplayOrder = 1199 -- Below the Hub, above normal game UI.
-- Native/manual callbacks can run without access to executor hidden UI hosts.
-- This passive receipt needs only ordinary PlayerGui, not Plugin privileges.
gui.Parent = ctx.pg
local function label(parent,text,x,y,w,h)
    local obj = Instance.new("TextLabel",parent)
    obj.Position,obj.Size = UDim2.fromOffset(x,y),UDim2.fromOffset(w,h)
    obj.BackgroundTransparency,obj.TextColor3,obj.TextSize = 1,Color3.fromRGB(230,235,245),20
    obj.Text,obj.TextWrapped,obj.Active = text,true,false
    obj.Font = Enum.Font.BuilderSans
    obj.TextStrokeTransparency=1
    return obj
end
local function round(obj,radius)
    Instance.new("UICorner",obj).CornerRadius=UDim.new(0,radius)
end
local restPosition=UDim2.new(1,-20,1,-24)
local toast = Instance.new("CanvasGroup",gui)
toast.Name,toast.Size = "PlantReceipt",UDim2.fromOffset(480,248)
toast.AnchorPoint,toast.Position = Vector2.new(1,1),restPosition
toast.BackgroundTransparency,toast.Visible,toast.Active = 1,false,false
toast.GroupTransparency=1
local scale=Instance.new("UIScale",toast); scale.Scale=1
local shadow=Instance.new("Frame",toast)
shadow.Name,shadow.Position,shadow.Size="Shadow",UDim2.fromOffset(4,8),UDim2.fromOffset(472,236)
shadow.BackgroundColor3,shadow.BackgroundTransparency=Color3.fromRGB(0,0,0),0.72
shadow.BorderSizePixel,shadow.Active=0,false; round(shadow,14)
local body=Instance.new("Frame",toast)
body.Name,body.Position,body.Size="Surface",UDim2.fromOffset(4,0),UDim2.fromOffset(472,236)
body.BackgroundColor3,body.BackgroundTransparency=Color3.fromRGB(7,17,30),0.08
body.BorderSizePixel,body.Active=0,false; round(body,12)
local border=Instance.new("UIStroke",body)
border.Color,border.Transparency,border.Thickness=Color3.fromRGB(57,169,255),0.4,1
local surfaceGradient=Instance.new("UIGradient",body)
surfaceGradient.Color=ColorSequence.new(Color3.fromRGB(255,255,255),Color3.fromRGB(205,215,235))
surfaceGradient.Rotation=90
local caption=label(body,"PLANT RECEIVED",18,10,250,28)
caption.Font,caption.TextXAlignment=Enum.Font.BuilderSansMedium,Enum.TextXAlignment.Left
caption.TextColor3=Color3.fromRGB(87,185,255)
local brand=label(body,"ADONIS HUB",282,10,172,28)
brand.TextColor3,brand.TextXAlignment=Color3.fromRGB(148,168,192),Enum.TextXAlignment.Right
local tile=Instance.new("Frame",body)
tile.Name,tile.Position,tile.Size="PlantVisual",UDim2.fromOffset(16,54),UDim2.fromOffset(120,152)
tile.BackgroundColor3,tile.BackgroundTransparency=Color3.fromRGB(26,61,91),0.4
tile.BorderSizePixel,tile.Active=0,false; round(tile,9)
local image = Instance.new("ImageLabel",tile)
image.Position,image.Size = UDim2.fromOffset(4,4),UDim2.fromOffset(112,144)
image.BackgroundTransparency,image.Visible = 1,false
image.ScaleType=Enum.ScaleType.Fit
local fallback = label(tile,"PLANT",4,4,112,144)
fallback.TextColor3=Color3.fromRGB(139,151,176)
local name = label(body,"",156,50,298,30)
name.Name,name.Font="PlantName",Enum.Font.BuilderSansBold
name.TextWrapped,name.TextTruncate=false,Enum.TextTruncate.AtEnd
local mutationCaption=label(body,"Mutation",156,88,92,30)
mutationCaption.TextColor3,mutationCaption.TextXAlignment=Color3.fromRGB(156,166,187),Enum.TextXAlignment.Left
local mutation = label(body,"",252,88,202,30)
mutation.Name,mutation.Font="Mutation",Enum.Font.BuilderSansBold
local mutationGradient=Instance.new("UIGradient",mutation)
mutationGradient.Enabled=false
mutationGradient.Color=ColorSequence.new({
    ColorSequenceKeypoint.new(0,Color3.fromRGB(255,119,138)),
    ColorSequenceKeypoint.new(0.2,Color3.fromRGB(255,219,108)),
    ColorSequenceKeypoint.new(0.4,Color3.fromRGB(104,239,161)),
    ColorSequenceKeypoint.new(0.6,Color3.fromRGB(98,208,255)),
    ColorSequenceKeypoint.new(0.8,Color3.fromRGB(186,147,255)),
    ColorSequenceKeypoint.new(1,Color3.fromRGB(255,119,194))})
local income = label(body,"",156,124,298,30)
income.Name,income.Font="Income",Enum.Font.BuilderSansBold
income.TextColor3=Color3.fromRGB(140,246,109)
local details = label(body,"",156,160,298,64)
details.Name,details.TextColor3="Details",Color3.fromRGB(160,171,192)
for _,obj in ipairs({name,mutation,income,details}) do obj.TextXAlignment = Enum.TextXAlignment.Left end
local track=Instance.new("Frame",body)
track.Name,track.Position,track.Size="LifetimeTrack",UDim2.fromOffset(18,228),UDim2.fromOffset(436,2)
track.BackgroundColor3,track.BackgroundTransparency,track.BorderSizePixel=Color3.fromRGB(255,255,255),0.94,0
local progress=Instance.new("Frame",track)
progress.Name,progress.Size,progress.BorderSizePixel="Lifetime",UDim2.new(1,0,1,0),0
progress.Active=false
local colors={normal=Color3.fromRGB(221,229,245),gold=Color3.fromRGB(255,211,84),
    diamond=Color3.fromRGB(91,182,255),emerald=Color3.fromRGB(77,226,146),
    ruby=Color3.fromRGB(255,100,120),rainbow=Color3.fromRGB(190,156,255)}
ctx.view.plantReceipt = toast
ctx.view.plantReceiptVisual,ctx.view.plantReceiptProgress=tile,progress
ctx.view.plantReceiptMutation,ctx.view.plantReceiptIncome=mutation,income
local enabledConnection=gui:GetPropertyChangedSignal("Enabled"):Connect(function()
    if ctx.state.alive and toast.Visible and not gui.Enabled then gui.Enabled=true end
end)

local function clearPreview()
    if preview then preview:Destroy(); preview = nil end
    image.Visible,fallback.Visible = false,true
end
local function cancelAnimations()
    receiptSerial=receiptSerial+1
    -- Disconnect first: Cancel may synchronously emit Completed(Cancelled).
    for _,connection in ipairs(tweenConnections) do connection:Disconnect() end
    tweenConnections={}
    for _,animation in ipairs(tweens) do animation:Cancel(); animation:Destroy() end
    tweens={}
end
local function animate(object,seconds,style,direction,goals,completed,repeats)
    local animation=TweenService:Create(object,TweenInfo.new(seconds,style,direction,repeats or 0),goals)
    table.insert(tweens,animation)
    if completed then
        local serial=receiptSerial
        table.insert(tweenConnections,animation.Completed:Connect(function(playback)
            if playback==Enum.PlaybackState.Completed and serial==receiptSerial and ctx.state.alive then completed() end
        end))
    end
    animation:Play()
end
local function hideReceipt()
    cancelAnimations()
    toast.Visible,exiting,expiresAt=false,false,nil
    clearPreview()
end
local function dismissReceipt()
    if not toast.Visible or exiting then return end
    cancelAnimations(); exiting=true
    animate(scale,exitSeconds,Enum.EasingStyle.Quad,Enum.EasingDirection.In,{Scale=receiptScale*0.98})
    animate(toast,exitSeconds,Enum.EasingStyle.Quad,Enum.EasingDirection.In,
        {Position=UDim2.new(1,8,1,-24),GroupTransparency=1},hideReceipt)
end
local function revealReceipt(system)
    exiting=false
    toast.Position,toast.GroupTransparency,toast.Visible=UDim2.new(1,24,1,-24),1,true
    gui.Enabled=true
    local viewport=workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
    receiptScale=viewport and math.clamp(math.min(1,(viewport.X-40)/480,(viewport.Y-48)/248),0.3,1) or 1
    scale.Scale=receiptScale*0.97
    progress.Size=UDim2.new(1,0,1,0)
    mutationGradient.Rotation=0
    mutationGradient.Enabled=system:lower()=="rainbow"
    if mutationGradient.Enabled then
        mutation.TextColor3=Color3.fromRGB(255,255,255)
        animate(mutationGradient,3.6,Enum.EasingStyle.Linear,Enum.EasingDirection.InOut,{Rotation=360},nil,-1)
    end
    animate(toast,0.32,Enum.EasingStyle.Quint,Enum.EasingDirection.Out,{Position=restPosition,GroupTransparency=0})
    animate(scale,0.32,Enum.EasingStyle.Quint,Enum.EasingDirection.Out,{Scale=receiptScale})
    -- Include the exit fade in the five-second display window.
    local holdSeconds=receiptSeconds-exitSeconds
    animate(progress,holdSeconds,Enum.EasingStyle.Linear,Enum.EasingDirection.Out,{Size=UDim2.new(0,0,1,0)},dismissReceipt)
    expiresAt=os.clock()+holdSeconds
end
local function plantImage(plant,system)
    clearPreview()
    local models=RS:FindFirstChild("PlantModels")
    local rarity=PlantConfig and PlantConfig.Rarities and PlantConfig.Rarities[plant.rarity]
    local tier=models and rarity and models:FindFirstChild(rarity.name)
    local source=tier and tier:FindFirstChild((plant.plant:gsub(" ","")))
    if not source or not source:IsA("Model") then return "model_unavailable" end
    if #source:GetDescendants()>400 then return "model_too_large" end
    local clone
    local ok,err=pcall(function()
        preview=Instance.new("ViewportFrame",tile)
        preview.Position,preview.Size=image.Position,image.Size
        preview.BackgroundTransparency=1
        preview.Ambient=Color3.fromRGB(210,220,235)
        preview.LightColor=Color3.fromRGB(255,249,235)
        local world=Instance.new("WorldModel",preview)
        local model=Instance.new("Model",world)
        clone=assert(source:Clone(),"Plant model cannot be cloned")
        local parts=0
        local look=PlantConfig and PlantConfig.MutationLook and PlantConfig.MutationLook[system]
        for _,obj in ipairs(clone:GetDescendants()) do
            if obj:IsA("LuaSourceContainer") or obj:IsA("Sound") or obj:IsA("ParticleEmitter")
                or obj:IsA("Trail") or obj:IsA("Beam") then obj:Destroy()
            elseif obj:IsA("BasePart") then
                parts=parts+1
                obj.Anchored,obj.CanCollide=true,false
                if look and look.main then
                    if look.main=="rainbow" then obj.Color=Color3.fromHSV((parts*0.07)%1,0.75,1)
                    else obj.Color=Color3.fromHex(look.main) end
                end
            end
        end
        if parts==0 then clone:Destroy();error("No plant geometry") end
        clone.Parent=model
        local cf,size=model:GetBoundingBox()
        local camera=Instance.new("Camera",preview)
        camera.FieldOfView=35
        local distance=math.max(size.X,size.Y,size.Z,0.1)/math.tan(math.rad(17.5))
        camera.CFrame=CFrame.new(cf.Position+Vector3.new(distance*0.7,distance*0.4,distance),cf.Position)
        preview.CurrentCamera=camera
        fallback.Visible=false
    end)
    if not ok then
        if clone then clone:Destroy() end
        clearPreview();return "unavailable: "..tostring(err)
    end
    return "plant_model"
end
local function compact(n)
    if type(n) ~= "number" or n~=n or math.abs(n)==math.huge then return "?" end
    local units = {"","K","M","B","T","Qa","Qi","Sx","Sp","Oc","No","Dc",
        "Ud","Dd","Td","Qad","Qid","Sxd","Spd","Ocd","Nod","Vg"}
    local i = 1
    while n >= 1000 and i < #units do n,i = n/1000,i+1 end
    return string.format("%.3g",n) .. units[i]
end
function ctx.showPlantReceipt(plant)
    cancelAnimations()
    name.Text=plant.plant
    local info=Balance and Balance.Mutations and Balance.Mutations[plant.mutation]
    local system=type(info)=="table" and info.name or (type(plant.mutation)=="string" and plant.mutation or "Normal")
    if system=="" then system="Normal" end
    if system:lower()=="emeral" then system="Emerald" end
    mutation.Text=system
    mutation.TextColor3=colors[system:lower()] or colors.normal
    progress.BackgroundColor3=colors[system:lower()] or colors.normal
    income.Text="Income: $"..compact(plant.income).."/s"
    local rarity=PlantConfig and PlantConfig.Rarities and PlantConfig.Rarities[plant.rarity]
    details.Text="Rarity: "..tostring(rarity and rarity.name or plant.rarity or "?")
        .."\nSize: x"..tostring(plant.size or "?")
    local visual=plantImage(plant,system)
    revealReceipt(system)
    ctx.state.lastPlantReceipt={id=tostring(plant.id),name=name.Text,mutation=system,
        income=plant.income,visual=visual}
end
cleanupPresentation=function()
    enabledConnection:Disconnect()
    hideReceipt(); gui:Destroy()
end
local notification={Gui=gui,Frame=toast}
function notification.Show(plant)
    if not ctx.state.alive then return false,"Notification has been destroyed" end
    if type(plant)~="table" or (type(plant.id)~="string" and type(plant.id)~="number")
        or type(plant.plant)~="string" or plant.plant=="" then
        return false,"Pass a confirmed Throw a Seed plant with id and name"
    end
    if ctx.state.lastPlantReceipt and ctx.state.lastPlantReceipt.id==tostring(plant.id) then
        return false,"Plant already shown"
    end
    ctx.showPlantReceipt(plant)
    return true
end
function notification.Hide()
    if ctx.state.alive then hideReceipt() end
end
function notification.Destroy()
    if not ctx.state.alive then return end
    ctx.state.alive=false
    for _,dispose in ipairs(ctx.disposers) do dispose() end
    ctx.disposers={}
end
return notification
end

end)()
plantReceipt=createPlantReceipt(pg)
end

end)()

factories["ui/Interactions"] = (function()
-- Adonis TAS module: ui/Interactions
-- Controller values are authoritative, including End and rejected toggles.
return function(context)
    setfenv(1, context)
refreshUI=function()
    for key,value in pairs(config) do
        if type(value)=="boolean" then menuUI.SetToggle(key,value,false)
        elseif type(value)=="number" then
            local box=menuUI.Controls[key]
            if box and not box:IsFocused() then menuUI.SetNumber(key,value,false) end
        end
    end
end
refreshUI()
notifyPlant=function(plant)
    local ok,reason=plantReceipt.Show(plant)
    if not ok then log("Plant receipt: "..tostring(reason)) end
end
end

end)()

factories["core/Runtime"] = (function()
-- Adonis TAS module: core/Runtime
-- Shared names belong to this session context, never the executor global table.
return function(context)
    setfenv(1, context)
controller={}
renderKey="AdonisTASCamera_"..session
controller.destroy=function(reason)
    if not alive then return end
    cancellation=cancellation+1
    emergency=true
    if not currentShot and not outstanding and training() then spawn(stopTraining) end
    log("Session closed: "..tostring(reason))
    flushFiles(true)
    alive=false
    if bridge and bridge.handler==observer then bridge.handler=nil end
    Run:UnbindFromRenderStep(renderKey)
    releasePresentation();restoreNativeSettings()
    for _,connection in ipairs(connections) do connection:Disconnect() end
    if menuUI then menuUI.Destroy() end
    if plantReceipt then plantReceipt.Destroy() end
    -- No fake Collect, physics unlock, or camera completion is issued on unload.
    if env.__AdonisTASMain==controller then env.__AdonisTASMain=nil end
end
env.__AdonisTASMain=controller
connect(UIS.InputBegan,function(input,processed)
    if input.KeyCode==Enum.KeyCode.End then emergencyStop()
    elseif not processed and not UIS:GetFocusedTextBox() and input.KeyCode==Enum.KeyCode.RightShift then toggleMenu() end
end)
connect(player.CharacterRemoving,function()
    cancellation=cancellation+1
    pendingIntent=nil;cycle=nil;throwRetry=nil;clearTrainingOffers();ownsTraining=false
    if currentShot then log("Respawn interrupted observed throw; no success counted") end
    currentShot=nil;releasePresentation()
    nativeAim=nil;resetNativeControl()
end)
renderErrorLogged=false
Run:BindToRenderStep(renderKey,Enum.RenderPriority.Camera.Value+20,function()
    if not alive then return end
    local ok,err=pcall(function()
        submitAtPerfect()
    end)
    if not ok and not renderErrorLogged then log("Render controller: "..tostring(err),"warning","render");renderErrorLogged=true end
end)

if config.EquipBest then equipDue=1 end
applyFPS()
applyMyPlants()
initialized=true
log("Build "..VERSION.." loaded. Input event="..tostring(throwInputOK).." ("..inputKind.."); observer="..tostring(observerOK)
    .."; state="..tostring(State~=nil).."; Balance="..tostring(Balance~=nil))
setStatus("San sang - bat tung chuc nang de chay")
spawn(function()
    while alive do
        coordinatorActive=true
        local ok,err=pcall(autoStep)
        coordinatorActive=false
        if not ok then
            setStatus("Tam cho sau loi: "..tostring(err))
            log("Automation paused after error: "..tostring(err),"warning","coordinator")
            task.wait(2)
        end
        task.wait(0.15)
    end
end)
spawn(function()
    while alive do
        local ok,err=pcall(serviceAutoTap)
        if not ok then log("XPBoost observer: "..tostring(err),"warning","xp-worker") end
        task.wait(0.1)
    end
end)
spawn(function()
    while alive do
        local ok,err=pcall(serviceRewards)
        if not ok then log("Reward worker: "..tostring(err),"warning","reward-worker") end
        task.wait(1)
    end
end)
spawn(function()
    while alive do
        local ok,err=pcall(serviceItemBoost)
        if not ok then log("Item Boost worker: "..tostring(err),"warning","item-worker") end
        task.wait(1)
    end
end)
spawn(function()
    while alive do
        local ok,err=pcall(function()
            -- Settings must keep applying after End and during native throws
            -- or pending farm requests. Their callbacks own the visual changes.
            if pendingProfile or pendingMyPlants then serviceNativeSettings() end
            if refreshNativeAutoSellUI then refreshNativeAutoSellUI() end
            if serviceCommunity then serviceCommunity() end
            if itemBoostView then menuUI.SetItemBoost(itemBoostView()) end
            if not throwInputOK and bindThrowInput() then
                throwInputOK=true
                log("Throw input ready: "..inputKind)
            end
            menuUI.SetStatus(status,not emergency and (currentShot~=nil or training()==true or outstanding~=nil))
            local view,inventoryError=inventoryView()
            menuUI.SetStorage(view,State and State.capacity,inventoryError)
            flushFiles(false)
        end)
        if not ok then log("UI/files update: "..tostring(err),"warning","ui-worker") end
        task.wait(0.75)
    end
end)
flushFiles(true)
end

end)()

-- Each run has its own shared context. A nil session slot must never inherit
-- a coincidentally named variable from another executor script.
local context = setmetatable({}, {__index = function(_, key)
    if sessionKeys[key] then return nil end
    return baseEnvironment[key]
end})
local function cleanupFailedLoad(message)
    if context.log then pcall(context.log, message) end
    if context.controller and context.controller.destroy then
        pcall(context.controller.destroy, "module load failure")
    else
        context.alive = false
        if context.bridge and context.bridge.handler == context.observer then context.bridge.handler = nil end
        for _, connection in ipairs(context.connections or {}) do pcall(function() connection:Disconnect() end) end
        if context.menuUI then pcall(context.menuUI.Destroy) end
        if context.plantReceipt then pcall(context.plantReceipt.Destroy) end
        if context.gui then pcall(function() context.gui:Destroy() end) end
        if context.flushFiles then pcall(context.flushFiles, true) end
    end
    warn("[Adonis TAS] " .. message)
end
for _, item in ipairs(moduleOrder) do
    local ok, err = pcall(factories[item[1]], context)
    if not ok then cleanupFailedLoad("Module " .. item[1] .. ": " .. tostring(err)); return end
    if item[1] == "core/Bootstrap" and (not context.pg or not context.scripts or not context.remotes) then
        cleanupFailedLoad("Client did not finish loading"); return
    end
end
